import { parameters as angularParameters } from '@storybook/angular-vite/client/config';

import docJson from '../documentation.json';

/**
 * Repairs the argTypes Storybook derives from compodoc.
 *
 * Storybook's Angular `extractType` only understands three shapes: the bare
 * primitives, and a union it can `JSON.parse` member-by-member.
 */
interface CompodocTypeAlias {
  name?: string;
  rawtype?: string;
}

interface CompodocVariable {
  name?: string;
  defaultValue?: string;
}

interface CompodocInterface {
  name?: string;
  properties?: { type?: string }[];
}

interface CompodocJson {
  interfaces?: CompodocInterface[];
  miscellaneous?: {
    typealiases?: CompodocTypeAlias[];
    variables?: CompodocVariable[];
  };
}

const misc = (docJson as CompodocJson).miscellaneous ?? {};

const NULLISH = new Set(['undefined', 'null']);

const INTERFACES = new Map<string, Required<CompodocInterface>>(
  ((docJson as CompodocJson).interfaces ?? [])
    .filter((entry): entry is Required<CompodocInterface> => !!entry.name && !!entry.properties)
    .map((entry) => [entry.name, entry]),
);

/**
 * Compodoc drops the index from an indexed-access alias, so
 * `type MudDateValue<M> = MudDateValueMap[M]` is recorded as the bare map
 * name and would render `valueChange` as `MudDateValueMap<M>`. The union of
 * the map's member types is what the alias can resolve to.
 */
const indexedAliasUnion = (rawtype: string): string | null => {
  const members = INTERFACES.get(rawtype)?.properties.flatMap((property) =>
    (property.type ?? '').split('|').map((member) => member.trim()),
  );

  if (!members?.length) return null;

  const unique = [...new Set(members.filter(Boolean))];
  const nullish = unique.filter((member) => NULLISH.has(member));

  return [...unique.filter((member) => !NULLISH.has(member)), ...nullish].join(' | ');
};

const TYPE_ALIASES = new Map<string, string>(
  (misc.typealiases ?? [])
    // Compodoc records a function-typed alias as the bare word `function`, which
    // would replace `MudTimeFilter` with something less informative than the name.
    .filter(
      (alias): alias is Required<CompodocTypeAlias> =>
        !!alias.name && !!alias.rawtype && alias.rawtype !== 'function',
    )
    .map((alias) => [alias.name, indexedAliasUnion(alias.rawtype) ?? alias.rawtype.replace(/"/g, "'")]),
);

const CONST_UNIONS = new Map<string, string>(
  (misc.variables ?? [])
    .filter(
      (variable): variable is Required<CompodocVariable> =>
        !!variable.name && !!variable.defaultValue,
    )
    .map((variable) => {
      const members = [...variable.defaultValue.matchAll(/'([^']*)'/g)].map(
        (match) => `'${match[1]}'`,
      );

      return [variable.name, members.join(' | ')] as const;
    })
    .filter(([, union]) => union.length > 0),
);

const TYPEOF_INDEX = /^typeof\s+(\w+)\['number'\]$/;

/** Follows alias -> alias -> `typeof CONST[number]` chains down to a concrete type. */
const resolveType = (type: string): string => {
  let current = type.trim();

  // Bounded: a self-referential alias would otherwise spin forever.
  for (let step = 0; step < 10; step += 1) {
    const alias = TYPE_ALIASES.get(current);

    if (alias) {
      current = alias;
      continue;
    }

    const constName = TYPEOF_INDEX.exec(current)?.[1];
    const union = constName ? CONST_UNIONS.get(constName) : undefined;

    if (!union) break;

    current = union;
  }

  return current;
};

const PRIMITIVES = new Set(['string', 'number', 'boolean']);
const STRING_LITERAL = /^'(.*)'$/;

interface Repair {
  type: { name: string; value?: readonly string[] };
  control: { type: string };
  options?: readonly string[];
}

const FUNCTION_TYPE = /=>/;

/**
 * Maps a fully resolved type to a usable control, or null to leave Storybook's
 * object control in place — correct for arrays, RegExp and generics, which
 * genuinely have no simpler editor. Function types never reach here.
 */
const repairFor = (resolved: string): Repair | null => {
  if (FUNCTION_TYPE.test(resolved) || /\[\]|[<>{}]/.test(resolved)) return null;

  const members = resolved
    .split('|')
    .map((member) => member.trim())
    .filter((member) => member && !NULLISH.has(member));

  if (members.length === 0) return null;

  const literals = members
    .map((member) => STRING_LITERAL.exec(member)?.[1])
    .filter((literal): literal is string => literal !== undefined);

  if (literals.length === members.length) {
    return {
      type: { name: 'enum', value: literals },
      // Matches the convention already used across the stories: a radio row
      // while the options stay scannable, a dropdown once they don't.
      control: { type: literals.length > 3 ? 'select' : 'inline-radio' },
      options: literals,
    };
  }

  if (!members.every((member) => PRIMITIVES.has(member))) return null;

  // `string | number` (badge content) still edits fine as text; a number-only
  // control would reject the string half.
  const kind = members.includes('string') ? 'string' : members.length === 1 ? members[0] : null;

  if (!kind) return null;

  return {
    type: { name: kind },
    control: { type: kind === 'string' ? 'text' : kind === 'number' ? 'number' : 'boolean' },
  };
};

/** True only for the broken fallback — never for a control the story set itself. */
const wantsRepair = (argType: { control?: unknown }): boolean => {
  const control = argType.control;

  if (control === false) return false;

  const controlType =
    typeof control === 'string' ? control : (control as { type?: string } | undefined)?.type;

  return controlType === undefined || controlType === 'object';
};

/**
 * The template API is inputs and outputs. Compodoc also reports public methods
 * and properties, which for these components means the `ControlValueAccessor`
 * plumbing every field must expose (`writeValue`, `registerOnChange`,
 * `setDisabledState`, ...) and underscore-prefixed internals that are public
 * only because a template binds them. Neither is something a consumer calls,
 * and both crowd out the real API — `mud-numeric-input` listed 44 rows.
 */
const isPublicApi = (name: string, category: unknown): boolean =>
  (category === 'inputs' || category === 'outputs') && !name.startsWith('_');

type ArgTypes = Record<string, ArgType>;
interface ArgType {
  name?: string;
  type?: unknown;
  control?: unknown;
  options?: unknown;
  table?: { category?: string; type?: { summary?: string; detail?: string } };
}

const baseExtractArgTypes = (
  angularParameters as { docs?: { extractArgTypes?: (component: unknown) => ArgTypes | undefined } }
).docs?.extractArgTypes;

/**
 * Wraps the framework's extractor rather than running as an `argTypesEnhancer`:
 * enhancers only see story contexts, so a `<ArgTypes of={MudRadio} />` block
 * that names a secondary component directly would bypass them and render raw,
 * unrepaired rows. Hooking extraction covers both paths, and runs before a
 * story's own `argTypes` are merged in, so those still win.
 */
export const extractArgTypes = (component: unknown): ArgTypes | undefined => {
  const extracted = baseExtractArgTypes?.(component);

  if (!extracted) return extracted;

  const argTypes: ArgTypes = Object.fromEntries(
    Object.entries(extracted).filter(([name, argType]) =>
      isPublicApi(name, argType?.table?.category),
    ),
  );

  for (const argType of Object.values(argTypes)) {
    const summary = argType?.table?.type?.summary;

    if (typeof summary !== 'string') continue;

    const referenced = [...TYPE_ALIASES.keys()].filter((name) =>
      new RegExp(`\\b${name}\\b`).test(summary),
    );

    // Show the members inline and keep `type MudButtonColor = ...` one click
    // away, so the reader learns both the values and the name.
    if (referenced.length > 0) {
      const expanded = referenced.reduce((acc, name) => {
        const resolved = resolveType(name);
        // A multi-member union spliced into a larger type needs parentheses to
        // keep its precedence readable. Function replacement: a literal `$` in
        // a member would otherwise act as a replacement pattern.
        const inlined = acc === name || !resolved.includes('|') ? resolved : `(${resolved})`;

        return acc.replace(new RegExp(`\\b${name}\\b(<[^<>]*>)?`, 'g'), () => inlined);
      }, summary);

      argType.table = {
        ...argType.table,
        type: {
          ...argType.table?.type,
          summary: expanded,
          detail: referenced.map((name) => `type ${name} = ${resolveType(name)}`).join('\n'),
        },
      };
    }

    // An output is an event the component emits, so there is nothing to set.
    // Storybook types outputs as `other`/`void`, which falls through to the
    // generic JSON editor — an "Edit JSON string..." box that does nothing
    // useful and, if typed into, assigns over the OutputEmitterRef.
    if (argType.table?.category === 'outputs') {
      argType.control = false as typeof argType.control;

      // Compodoc reports a plain `output<T>()` as just `T` (or `void`), while
      // Storybook renders a model's change output as `(e: T) => void`. Show
      // every output as the handler signature so the payload type reads the
      // same way in both rows.
      const emitted = argType.table.type?.summary;

      if (typeof emitted === 'string' && !emitted.includes('=>')) {
        argType.table = {
          ...argType.table,
          type: {
            ...argType.table.type,
            summary: emitted === 'void' ? '() => void' : `(e: ${emitted}) => void`,
          },
        };
      }

      continue;
    }

    // A function input has the same problem as an output: the JSON editor
    // cannot express a callback, and whatever is typed in replaces the
    // function the component later invokes. The type column still carries the
    // signature, which is the part a reader needs.
    if (FUNCTION_TYPE.test(resolveType(argType.table?.type?.summary ?? summary))) {
      argType.control = false as typeof argType.control;
      continue;
    }

    if (argType.table?.category !== 'inputs' || !wantsRepair(argType)) continue;

    const repair = repairFor(resolveType(argType.table.type?.summary ?? summary));

    if (!repair) continue;

    argType.type = repair.type as typeof argType.type;
    argType.control = repair.control as typeof argType.control;

    if (repair.options) argType.options = repair.options as typeof argType.options;
  }

  return argTypes;
};

import { afterNextRender, Component, viewChild } from '@angular/core';
import type { Meta, StoryObj } from '@storybook/angular-vite';
import { applicationConfig, moduleMetadata } from '@storybook/angular-vite';
import { MudPagination, provideMudPaginationLabels } from 'ngx-mud-ui/pagination';
import type { MudPaginationLabels, MudPaginationSize } from 'ngx-mud-ui/pagination';
import {
  MudCell,
  MudCellDef,
  MudColumnDef,
  MudHeaderCell,
  MudHeaderCellDef,
  MudHeaderRow,
  MudHeaderRowDef,
  MudRow,
  MudRowDef,
  MudSort,
  MudSortHeader,
  MudTable,
  MudTableDataSource,
} from 'ngx-mud-ui/table';

interface PlaygroundArgs {
  length: number;
  pageSize: number;
  pageIndex: number;
  disabled: boolean;
  size: MudPaginationSize;
  'aria-label': string;
}

const playgroundSource = (args: PlaygroundArgs): string => `import { Component, signal } from '@angular/core';
import { MudPagination, type MudPageEvent } from 'ngx-mud-ui/pagination';

@Component({
  selector: 'app-results',
  imports: [MudPagination],
  template: \`
    <mud-pagination
      [length]="${args.length}"
      [pageSize]="${args.pageSize}"
      [(pageIndex)]="pageIndex"
      [disabled]="${args.disabled}"
      size="${args.size}"
      aria-label="${args['aria-label']}"
      (page)="load($event)"
    />
  \`,
})
export class ResultsComponent {
  readonly pageIndex = signal(${args.pageIndex});
  load(event: MudPageEvent) { /* fetch page event.pageIndex */ }
}`;

const meta: Meta<MudPagination> = {
  title: 'Components/Pagination',
  component: MudPagination,
  decorators: [moduleMetadata({ imports: [MudPagination] })],
  argTypes: {
    length: { control: { type: 'number', min: 0 } },
    pageSize: { control: { type: 'number', min: 1 } },
    pageIndex: { control: { type: 'number', min: 0 } },
    disabled: { control: 'boolean' },
    size: { control: 'inline-radio', options: ['small', 'medium'] },
    'aria-label': { control: 'text' },
  } as Meta<MudPagination>['argTypes'],
  args: {
    length: 200,
    pageSize: 10,
    pageIndex: 4,
    disabled: false,
    size: 'medium',
    'aria-label': 'Pagination',
  } as Meta<MudPagination>['args'],
};

export default meta;

type Story = StoryObj<MudPagination>;

/** Every input bound — drop the length to 50 and the overflows disappear. */
export const Playground: Story = {
  parameters: {
    docs: { source: { language: 'ts', transform: (_c: string, ctx: { args: PlaygroundArgs }) => playgroundSource(ctx.args) } },
  },
  render: (args) => {
    const a = args as unknown as PlaygroundArgs;

    return {
      props: { ...a, label: a['aria-label'] },
      template: `
        <mud-pagination
          [length]="length"
          [pageSize]="pageSize"
          [(pageIndex)]="pageIndex"
          [disabled]="disabled"
          [size]="size"
          [aria-label]="label"
        />
      `,
    };
  },
};

/** Both rungs: 40px with Prev/Next text, 32px icon-only. */
export const Sizes: Story = {
  parameters: { controls: { disable: true } },
  render: () => ({
    template: `
      <div style="display:grid;gap:24px">
        <mud-pagination [length]="200" [pageIndex]="4" />
        <mud-pagination [length]="200" [pageIndex]="4" size="small" />
      </div>
    `,
  }),
};

/** Seven pages or fewer: every page is shown, no overflow. One page renders nothing. */
export const FewPages: Story = {
  parameters: { controls: { disable: true } },
  render: () => ({
    template: `
      <div style="display:grid;gap:24px">
        <mud-pagination [length]="70" [pageIndex]="3" />
        <mud-pagination [length]="30" [pageIndex]="0" />
        <mud-pagination [length]="8" />
      </div>
    `,
  }),
};

/** The Figma windowing rules, one row per case. Open a `…` to jump into the collapsed range. */
export const ManyPages: Story = {
  parameters: { controls: { disable: true } },
  render: () => ({
    template: `
      <div style="display:grid;gap:24px">
        <mud-pagination [length]="200" [pageIndex]="0" />
        <mud-pagination [length]="200" [pageIndex]="4" />
        <mud-pagination [length]="200" [pageIndex]="9" />
        <mud-pagination [length]="200" [pageIndex]="16" />
        <mud-pagination [length]="200" [pageIndex]="19" />
      </div>
    `,
  }),
};

export const Disabled: Story = {
  parameters: { controls: { disable: true } },
  render: () => ({ template: `<mud-pagination [length]="200" [pageIndex]="9" disabled />` }),
};

/** Drag the box's corner: below the 7-slot width it drops to 5 slots. */
export const NarrowContainer: Story = {
  parameters: { controls: { disable: true } },
  render: () => ({
    template: `
      <div style="resize:horizontal;overflow:auto;inline-size:520px;max-inline-size:100%;padding:12px;border:1px dashed var(--mud-color-border-base-default)">
        <mud-pagination [length]="200" [pageIndex]="9" />
      </div>
    `,
  }),
};

const RO_LABELS: Partial<MudPaginationLabels> = {
  navigation: 'Navigare pagini',
  previous: 'Anterior',
  next: 'Următor',
  previousAria: (page) => `Pagina anterioară, mergi la pagina ${page}`,
  nextAria: (page) => `Pagina următoare, mergi la pagina ${page}`,
  pageAria: (page, total) => `Pagina ${page} din ${total}`,
  overflowAria: (from, to) => `Arată paginile de la ${from} la ${to}`,
};

/** Romanian strings through provideMudPaginationLabels — one call localizes every paginator. */
export const LocalizedLabels: Story = {
  parameters: { controls: { disable: true } },
  decorators: [applicationConfig({ providers: [provideMudPaginationLabels(RO_LABELS)] })],
  render: () => ({ template: `<mud-pagination [length]="200" [pageIndex]="9" />` }),
};

interface Cerere {
  id: number;
  nume: string;
  suma: number;
}

const CERERI: Cerere[] = Array.from({ length: 47 }, (_v, i) => ({
  id: i + 1,
  nume: ['Ana Rusu', 'Ion Ceban', 'Maria Popescu', 'Victor Lungu', 'Elena Cojocaru'][i % 5],
  suma: ((i * 37) % 900) + 100,
}));

@Component({
  selector: 'mud-pagination-story-table',
  imports: [
    MudTable,
    MudColumnDef,
    MudHeaderCellDef,
    MudCellDef,
    MudHeaderCell,
    MudCell,
    MudHeaderRowDef,
    MudRowDef,
    MudHeaderRow,
    MudRow,
    MudSort,
    MudSortHeader,
    MudPagination,
  ],
  template: `
    <div class="mud-data-table-container">
      <table mud-table [dataSource]="source" mudSort (sortChange)="paginator().firstPage()" aria-label="Cereri depuse">
        <ng-container mudColumnDef="id">
          <th mud-header-cell *mudHeaderCellDef mud-sort-header>Nr.</th>
          <td mud-cell *mudCellDef="let row">{{ row.id }}</td>
        </ng-container>
        <ng-container mudColumnDef="nume">
          <th mud-header-cell *mudHeaderCellDef mud-sort-header>Nume</th>
          <td mud-cell *mudCellDef="let row">{{ row.nume }}</td>
        </ng-container>
        <ng-container mudColumnDef="suma">
          <th mud-header-cell *mudHeaderCellDef mud-sort-header>Suma</th>
          <td mud-cell *mudCellDef="let row">{{ row.suma }}</td>
        </ng-container>
        <tr mud-header-row *mudHeaderRowDef="columns"></tr>
        <tr mud-row *mudRowDef="let row; columns: columns"></tr>
      </table>
    </div>
    <mud-pagination [pageSize]="5" style="justify-content:flex-end;margin-block-start:16px" />
  `,
})
class PagedTable {
  readonly columns = ['id', 'nume', 'suma'];
  readonly source = new MudTableDataSource(CERERI);
  readonly sort = viewChild.required(MudSort);
  readonly paginator = viewChild.required(MudPagination);

  constructor() {
    afterNextRender(() => {
      this.source.sort = this.sort();
      this.source.paginator = this.paginator();
    });
  }
}

// "Show code" for WithTable: the PagedTable host above as a pasteable app component. Keep the two in sync.
const WITH_TABLE_SOURCE = `import { afterNextRender, Component, viewChild } from '@angular/core';
import { MudPagination } from 'ngx-mud-ui/pagination';
import {
  MudCell,
  MudCellDef,
  MudColumnDef,
  MudHeaderCell,
  MudHeaderCellDef,
  MudHeaderRow,
  MudHeaderRowDef,
  MudRow,
  MudRowDef,
  MudSort,
  MudSortHeader,
  MudTable,
  MudTableDataSource,
} from 'ngx-mud-ui/table';

interface Cerere {
  id: number;
  nume: string;
  suma: number;
}

const CERERI: Cerere[] = Array.from({ length: 47 }, (_v, i) => ({
  id: i + 1,
  nume: ['Ana Rusu', 'Ion Ceban', 'Maria Popescu', 'Victor Lungu', 'Elena Cojocaru'][i % 5],
  suma: ((i * 37) % 900) + 100,
}));

@Component({
  selector: 'app-cereri',
  imports: [
    MudTable,
    MudColumnDef,
    MudHeaderCellDef,
    MudCellDef,
    MudHeaderCell,
    MudCell,
    MudHeaderRowDef,
    MudRowDef,
    MudHeaderRow,
    MudRow,
    MudSort,
    MudSortHeader,
    MudPagination,
  ],
  template: \`
    <div class="mud-data-table-container">
      <!-- re-sorting goes back to page 1; drop the handler to keep the current page -->
      <table mud-table [dataSource]="source" mudSort (sortChange)="paginator().firstPage()" aria-label="Cereri depuse">
        <ng-container mudColumnDef="id">
          <th mud-header-cell *mudHeaderCellDef mud-sort-header>Nr.</th>
          <td mud-cell *mudCellDef="let row">{{ row.id }}</td>
        </ng-container>
        <ng-container mudColumnDef="nume">
          <th mud-header-cell *mudHeaderCellDef mud-sort-header>Nume</th>
          <td mud-cell *mudCellDef="let row">{{ row.nume }}</td>
        </ng-container>
        <ng-container mudColumnDef="suma">
          <th mud-header-cell *mudHeaderCellDef mud-sort-header>Suma</th>
          <td mud-cell *mudCellDef="let row">{{ row.suma }}</td>
        </ng-container>
        <tr mud-header-row *mudHeaderRowDef="columns"></tr>
        <tr mud-row *mudRowDef="let row; columns: columns"></tr>
      </table>
    </div>
    <!-- the host is a block-level flex container: justify-content aligns the paginator -->
    <mud-pagination [pageSize]="5" style="justify-content: flex-end; margin-block-start: 16px" />
  \`,
})
export class CereriComponent {
  readonly columns = ['id', 'nume', 'suma'];
  // Sorts, then slices one page; it also keeps the paginator's length up to date.
  readonly source = new MudTableDataSource(CERERI);
  readonly sort = viewChild.required(MudSort);
  readonly paginator = viewChild.required(MudPagination);

  constructor() {
    // viewChild resolves after the first render, so hand both over then.
    afterNextRender(() => {
      this.source.sort = this.sort();
      this.source.paginator = this.paginator();
    });
  }
}`;

/** The table recipe: sort, then page. Re-sorting jumps back to page 1 via `(sortChange)`. */
export const WithTable: Story = {
  parameters: { controls: { disable: true }, docs: { source: { code: WITH_TABLE_SOURCE, language: 'ts' } } },
  decorators: [moduleMetadata({ imports: [PagedTable] })],
  render: () => ({ template: `<mud-pagination-story-table />` }),
};

import type { Meta, StoryObj } from '@storybook/angular-vite';
import { applicationConfig, moduleMetadata } from '@storybook/angular-vite';
import { afterNextRender, ChangeDetectionStrategy, Component, inject, input, linkedSignal, output, signal, viewChild } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { HttpClient, HttpResponse, provideHttpClient, withInterceptors } from '@angular/common/http';
import type { HttpInterceptorFn } from '@angular/common/http';
import { delay, of } from 'rxjs';
import { SelectionModel } from '@angular/cdk/collections';
import { MudSpinner } from 'ngx-mud-ui/spinner';
import { MudCheckbox } from 'ngx-mud-ui/checkbox';
import { MudTag } from 'ngx-mud-ui/tag';
import { MudIconButton } from 'ngx-mud-ui/button';
import { MudPagination } from 'ngx-mud-ui/pagination';
import { edit, MudIconComponent, provideMudIcons } from 'ngx-mud-ui/icons';
import {
  MudCell,
  MudCellDef,
  MudColumnDef,
  MudFooterCell,
  MudFooterCellDef,
  MudFooterRow,
  MudFooterRowDef,
  MudHeaderCell,
  MudHeaderCellDef,
  MudHeaderRow,
  MudHeaderRowDef,
  MudNoDataRow,
  MudRow,
  MudRowDef,
  MudSort,
  MudSortHeader,
  MudTable,
  MudTableDataSource,
} from 'ngx-mud-ui/table';
import type { MudSortDirection, MudSortState, MudTableHeaderStyle, MudTableRowStyle } from 'ngx-mud-ui/table';

interface Cerere {
  id: number;
  nume: string;
  localitate: string;
  depusa: string;
  suma: number;
  stare: string;
}

const CERERI: Cerere[] = [
  { id: 1, nume: 'Ana Rusu', localitate: 'Chișinău', depusa: '2026-09-01', suma: 250, stare: 'În examinare' },
  { id: 2, nume: 'Ion Ceban', localitate: 'Bălți', depusa: '2026-08-28', suma: 1200, stare: 'Aprobată' },
  { id: 3, nume: 'Maria Popescu', localitate: 'Cahul', depusa: '2026-09-10', suma: 80, stare: 'Respinsă' },
  { id: 4, nume: 'Vasile Lungu', localitate: 'Orhei', depusa: '2026-09-05', suma: 640, stare: 'Aprobată' },
  { id: 5, nume: 'Elena Moraru', localitate: 'Ungheni', depusa: '2026-08-30', suma: 310, stare: 'În examinare' },
];

const COLUMNS = ['nume', 'localitate', 'depusa', 'suma'];

// 47 generated requests for the pagination stories (five rows would fit on one page).
const NUME = ['Ana Rusu', 'Ion Ceban', 'Maria Popescu', 'Vasile Lungu', 'Elena Moraru', 'Victor Cojocaru', 'Natalia Grosu'];
const LOCALITATI = ['Chișinău', 'Bălți', 'Cahul', 'Orhei', 'Ungheni', 'Soroca', 'Comrat'];
const STARI = ['În examinare', 'Aprobată', 'Respinsă'];
const CERERI_MANY: Cerere[] = Array.from({ length: 47 }, (_v, i) => ({
  id: i + 1,
  nume: NUME[i % NUME.length],
  localitate: LOCALITATI[(i * 3 + Math.floor(i / NUME.length)) % LOCALITATI.length],
  depusa: `2026-0${String(8 + (i % 2))}-${String((i % 28) + 1).padStart(2, '0')}`,
  suma: ((i * 137) % 1900) + 50,
  stare: STARI[i % STARI.length],
}));

