    '  readonly someSelected = signal(false);',
    '',
    '  toggle(row: Cerere): void {',
    '    this.selection.toggle(row);',
    '    this.refresh();',
    '  }',
    '',
    '  toggleAll(): void {',
    '    if (this.selection.selected.length === this.rows.length) {',
    '      this.selection.clear();',
