      border-top: 1px solid var(--mud-color-border-base-default);
    }
    .name {
      font-family: ui-monospace, monospace;
      font-size: 0.78rem;
    }
    .value {
      font-size: 0.75rem;
      color: var(--mud-color-text-base-secondary);
      overflow-wrap: anywhere;
    }
    .swatch--spacing {
      display: block;
      height: 0.75rem;
      max-width: 8rem;
      background: var(--mud-color-background-brand-default);
    }
    .swatch--box {
      display: block;
