      height: 2rem;
      background: var(--mud-color-background-base-default);
      border: 1px solid var(--mud-color-border-base-default);
    }
  `,
})
export class TokenReferenceComponent {
  private readonly _document = inject(DOCUMENT);

  protected readonly shared = signal<Group[]>([]);
  protected readonly component = signal<Group[]>([]);

  constructor() {
    afterNextRender(() => this._load());
  }

  private _load(): void {
    const tokens = this._rootTokens();
    const taken = new Set<string>();

    this.shared.set(
      SHARED.map(({ title, kind, match }) => {
        const list = tokens.filter((t) => match.test(t.name) && !taken.has(t.name));

        list.forEach((t) => taken.add(t.name));

        return { title, kind, tokens: list };
      }).filter((g) => g.tokens.length),
    );

    const byComponent = new Map<string, Token[]>();

    for (const token of tokens) {
      if (taken.has(token.name) || COLOR_LITERAL.test(token.value)) continue;

      const owner = ownerOf(token.name);

      if (owner) byComponent.set(owner, [...(byComponent.get(owner) ?? []), token]);
    }
    this.component.set([...byComponent].map(([title, list]) => ({ title, kind: 'plain', tokens: list })));
  }

  private _rootTokens(): Token[] {
    const found = new Map<string, string>();

    for (const sheet of Array.from(this._document.styleSheets)) {
      let rules: CSSRule[];

      try {
        rules = unlayeredRules(sheet.cssRules);
      } catch {
        continue;
      }
      for (const rule of rules) {
        if (!(rule instanceof CSSStyleRule) || rule.selectorText.trim() !== ':root') continue;

        for (const name of Array.from(rule.style)) {
          if (name.startsWith('--mud-') && !name.startsWith('--mud-color-')) found.set(name, rule.style.getPropertyValue(name).trim());
        }
      }
    }

    return [...found].map(([name, value]) => ({ name, value })).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }
}

import { vi } from 'vitest';

// Vitest's jsdom environment exposes the underlying JSDOM instance as a
// documented global (typed via `vitest/jsdom`, not enabled project-wide here)
// specifically so tests can reach `virtualConsole`. Minimally typed inline
// rather than adding that types entry for the whole project.
type JsdomVirtualConsoleListener = (error: Error) => void;
interface JsdomVirtualConsole {
  listeners: (event: 'jsdomError') => JsdomVirtualConsoleListener[];
  removeAllListeners: (event: 'jsdomError') => void;
  on: (event: 'jsdomError', listener: JsdomVirtualConsoleListener) => void;
}

/**
 * jsdom has no real navigation: clicking a real `<a href>` whose default was
 * not prevented makes jsdom attempt to navigate, which logs "Not implemented:
 * navigation to another Document" straight to `process.stderr` — jsdom's
 * VirtualConsole forwards `jsdomError` there directly, bypassing `console`
 * spies entirely (verified by instrumenting `process.stderr.write` directly;
 * a `vi.spyOn(console, 'error')` sees nothing even though the warning still
 * prints).
 *
 * For a test that deliberately leaves a click's default un-prevented (to
 * prove open-in-new-tab still works), this swaps the VirtualConsole's
 * `jsdomError` listener for a spy for the duration of `run`, so the resulting
 * navigation attempt is captured instead of printed to the test output — and
 * is itself the strongest evidence the click's default was genuinely left
 * alone, since a buggy guard could satisfy `defaultPrevented === false` via
 * an unrelated early return without ever reaching real navigation. The
 * original listeners are always restored, even if `run` throws.
 *
 * ```ts
 * const navigationAttempted = await withSwappedVirtualConsole(async () => {
 *   el.dispatchEvent(event);
 *   await fixture.whenStable();
 *   await new Promise((resolve) => setTimeout(resolve, 0));
 * });
 *
 * expect(navigationAttempted).toHaveBeenCalledWith(
 *   expect.objectContaining({ message: expect.stringContaining('Not implemented') }),
 * );
 * ```
 */
export async function withSwappedVirtualConsole(
  run: () => Promise<void> | void,
): Promise<ReturnType<typeof vi.fn<JsdomVirtualConsoleListener>>> {
  const virtualConsole = (
    globalThis as unknown as { jsdom: { virtualConsole: JsdomVirtualConsole } }
  ).jsdom.virtualConsole;
  const defaultListeners = virtualConsole.listeners('jsdomError');
  const navigationAttempted = vi.fn<JsdomVirtualConsoleListener>();

  virtualConsole.removeAllListeners('jsdomError');
  virtualConsole.on('jsdomError', navigationAttempted);

  try {
    await run();
  } finally {
    virtualConsole.removeAllListeners('jsdomError');
    defaultListeners.forEach((listener) => virtualConsole.on('jsdomError', listener));
  }

  return navigationAttempted;
}

import { isPlatformBrowser } from '@angular/common';
import {
  booleanAttribute,
  computed,
  Directive,
  effect,
  ElementRef,
  inject,
  input,
  PLATFORM_ID,
  signal,
  ViewContainerRef,
} from '@angular/core';
import { MudTooltip } from 'ngx-mud-ui/tooltip';

declare const ngDevMode: boolean | undefined;

/** State the parent breadcrumb assigns; a crumb never decides these for itself. */
export interface MudBreadcrumbItemState {
  collapsed: boolean;
  current: boolean;
}

/** Labels longer than this truncate with an ellipsis and grow a tooltip. */
const TRUNCATE_AT = 30;

/** Elements that can be the crumb's real click/focus target inside the <li>. */
const INTERACTIVE = 'a,button';

/** Tag names and roles that make the crumb's surroundings a genuine list. */
const LIST_TAGS = new Set(['OL', 'UL', 'MENU']);

/**
 * ```html
 * <li mudBreadcrumbItem><a routerLink="/servicii">Servicii</a></li>
 * <li mudBreadcrumbItem active><span>Cerere nouă</span></li>
 * ```
 *
 * Sits on the `<li>`, so the trail is a real `<nav><ol><li>` list; the
 * consumer's own anchor stays inside it and keeps `routerLink`. ARIA state and
 * the tooltip are redirected onto that anchor — see `target()`.
 *
 * The truncation tooltip is driven by `text()`, which falls back to
 * `element.textContent` — a non-reactive DOM read, so it only re-evaluates
 * when the `label` input changes, not when projected content changes on its own.
 */
@Directive({
  selector: '[mudBreadcrumbItem]',
  exportAs: 'mudBreadcrumbItem',
  hostDirectives: [MudTooltip],
  host: {
    class: 'mud-breadcrumb__item',
    '[class.mud-breadcrumb__item--active]': 'isCurrent()',
    '[class.mud-breadcrumb__item--disabled]': 'disabled()',
    '[class.mud-breadcrumb__item--collapsed]': 'collapsed()',
  },
})
export class MudBreadcrumbItem {
  /** The consumer's `<li>`. The crumb's box, not its click target — see `target()`. */
  readonly element: HTMLElement = inject(ElementRef).nativeElement;
  /** Anchors views immediately after this element; the overflow trigger uses it. */
  readonly viewContainerRef = inject(ViewContainerRef);

  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
  private readonly _state = signal<MudBreadcrumbItemState>({ collapsed: false, current: false });
  private readonly _tooltip = inject(MudTooltip, { self: true });

  private _ariaTarget: HTMLElement | null = null;
  private _warnedAboutStructure = false;

  /** @description Marks this crumb as the current page. Renders as text, never underlined. */
  readonly active = input(false, { transform: booleanAttribute });
  /** @description Blocks activation and greys the crumb out, while keeping it focusable. */
  readonly disabled = input(false, { transform: booleanAttribute });
  /** @description Text override for the overflow panel and back link when content is not plain text. */
  readonly label = input<string | undefined>(undefined);

  /** True when this crumb is the current page, whether set explicitly or resolved by the parent. */
  readonly isCurrent = computed(() => this.active() || this._state().current);
  /** True while this crumb lives in the overflow panel instead of the trail. */
  readonly collapsed = computed(() => this._state().collapsed);

  private readonly _tooltipContent = computed(() => {
    const text = this.text();

    return text.length > TRUNCATE_AT ? text : null;
  });

  constructor() {
    if (this._isBrowser) {
      this.element.addEventListener('click', (event) => this._blockInert(event), { capture: true });
    }

    effect(() => {
      this._tooltip.setContent(this._tooltipContent());
      // Read both states so the effect re-runs when either flips.
      this._syncAria(this.isCurrent(), this.disabled());
    });
  }

  /** Called by MudBreadcrumb. Crumbs never manage their own collapse or current state. */
  setState(state: MudBreadcrumbItemState): void {
    this._state.set(state);
  }

  /**
   * The crumb's real interactive element — the consumer's `<a>` or `<button>`
   * inside the `<li>`, or the `<li>` itself for a plain text crumb. This is what
   * a synthesised click must hit; firing on the `<li>` would never run routerLink.
   */
  target(): HTMLElement {
    return this.element.querySelector<HTMLElement>(INTERACTIVE) ?? this.element;
  }

  /** Text for the overflow panel and the back link. */
  text(): string {
    return this.label() ?? this.element.textContent?.trim() ?? '';
  }

  /** Resolved navigation target, or null for a text crumb. routerLink writes this attribute. */
  href(): string | null {
    return this.target().getAttribute('href');
  }

  private _syncAria(current: boolean, disabled: boolean): void {
    const target = this.target();

    if (this._ariaTarget && this._ariaTarget !== target) {
      this._ariaTarget.removeAttribute('aria-current');
      this._ariaTarget.removeAttribute('aria-disabled');
    }

    this._ariaTarget = target;
    this._toggleAttribute(target, 'aria-current', current ? 'page' : null);
    this._toggleAttribute(target, 'aria-disabled', disabled ? 'true' : null);
    // The tooltip's host is the <li>, which is neither focusable nor described;
    // point its aria-describedby and its overlay at the same control.
    this._tooltip.setAnchor(target === this.element ? null : target);
    this._warnAboutStructure();
  }

  private _toggleAttribute(element: HTMLElement, name: string, value: string | null): void {
    if (value === null) {
      element.removeAttribute(name);
    } else {
      element.setAttribute(name, value);
    }
  }

  private _warnAboutStructure(): void {
    if (this._warnedAboutStructure) return;

    if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

    const parent = this.element.parentElement;
    const isListItem =
      this.element.tagName === 'LI' || this.element.getAttribute('role') === 'listitem';
    const inList =
      parent !== null &&
      (LIST_TAGS.has(parent.tagName) || parent.getAttribute('role') === 'list');

    if (isListItem && inList) return;

    this._warnedAboutStructure = true;
    console.warn(
      `[mud-breadcrumb] mudBreadcrumbItem belongs on an <li> inside the <ol> of a ` +
        `<nav mudBreadcrumb> (got <${this.element.tagName.toLowerCase()}> in ` +
        `<${parent?.tagName.toLowerCase() ?? 'nothing'}>). Without that, the trail ` +
        `renders correctly but screen readers never announce it as a list.`,
    );
  }

  private _blockInert(event: Event): void {
    if (!this.disabled() && !this.isCurrent()) return;

    event.preventDefault();
    event.stopImmediatePropagation();
  }
}

export interface MudCivilDate {
  y: number;
  m: number;
  d: number;
}

const ISO_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Days between the civil date and 1970-01-01, by Howard Hinnant's
 * `days_from_civil`. Pure integer arithmetic — no `Date`, so no timezone or
 * DST transition can influence the result.
 */
function daysFromCivil({ y, m, d }: MudCivilDate): number {
  const year = y - (m <= 2 ? 1 : 0);
  const era = Math.floor(year / 400);
  const yoe = year - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;

  return era * 146097 + doe - 719468;
}

/** Inverse of {@link daysFromCivil}. */
function civilFromDays(days: number): MudCivilDate {
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365,
  );
  const year = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);

  return { y: year + (m <= 2 ? 1 : 0), m, d };
}

export function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

/** `month` is 1-indexed. */
export function daysInMonth(year: number, month: number): number {
  if (month === 2) return isLeapYear(year) ? 29 : 28;

  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

/**
 * True only for a `YYYY-MM-DD` string naming a date that exists. Datetime
 * strings are rejected on purpose — see the strict-format decision in the spec.
 */
export function isValidIso(value: string): boolean {
  const match = ISO_PATTERN.exec(value);

  if (!match) return false;

  const y = Number(match[1]);
  const m = Number(match[2]);
  const d = Number(match[3]);

  return m >= 1 && m <= 12 && d >= 1 && d <= daysInMonth(y, m);
}

export function parseIso(value: string): MudCivilDate | null {
  if (!isValidIso(value)) return null;

  return { y: Number(value.slice(0, 4)), m: Number(value.slice(5, 7)), d: Number(value.slice(8, 10)) };
}

export function toIso({ y, m, d }: MudCivilDate): string {
  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

/** Years outside this range cannot round-trip through a four-digit ISO string. */
function isRepresentable({ y }: MudCivilDate): boolean {
  return y >= 0 && y <= 9999;
}

/** 0 = Sunday … 6 = Saturday. 1970-01-01 was a Thursday, hence the +4. */
export function dayOfWeek(iso: string): number {
  const date = parseIso(iso);

  if (!date) return 0;

  return (((daysFromCivil(date) + 4) % 7) + 7) % 7;
}

export function addDays(iso: string, amount: number): string {
  const date = parseIso(iso);

  if (!date) return iso;

  const next = civilFromDays(daysFromCivil(date) + amount);

  return isRepresentable(next) ? toIso(next) : iso;
}

/** Clamps the day to the target month's length: Jan 31 + 1 month = Feb 28/29. */
export function addMonths(iso: string, amount: number): string {
  const date = parseIso(iso);

  if (!date) return iso;

  const total = date.y * 12 + (date.m - 1) + amount;
  const y = Math.floor(total / 12);
  const m = (((total % 12) + 12) % 12) + 1;
  const next = { y, m, d: Math.min(date.d, daysInMonth(y, m)) };

  return isRepresentable(next) ? toIso(next) : iso;
}

/** First day of the containing month; unusable input passes through. */
export function startOfMonth(iso: string): string {
  const date = parseIso(iso);

  return date ? toIso({ ...date, d: 1 }) : iso;
}

/** ISO dates sort lexicographically, so this is a plain string comparison. */
export function compareIso(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Orders a range's endpoints, so entering the later date first still yields a
 * valid range. Shared by the calendar's range-completion path and the field's
 * range commit — the two used to make opposite choices for the same user
 * intent (the calendar swapped, the field nullified the end), which is exactly
 * what a shared helper prevents from drifting apart again.
 */
export function normalizeRange(a: string, b: string): { start: string; end: string } {
  return compareIso(a, b) <= 0 ? { start: a, end: b } : { start: b, end: a };
}

/** Inclusive on both bounds; an absent bound is unbounded. */
export function isWithin(iso: string, min?: string, max?: string): boolean {
  if (min && compareIso(iso, min) < 0) return false;

  if (max && compareIso(iso, max) > 0) return false;

  return true;
}

/** Passes an ISO date through, and anything else out. Bounds arriving from a
 *  signal-forms schema are name-matched at runtime and are not type-checked. */
export function toValidIsoOrUndefined(value: unknown): string | undefined {
  return typeof value === 'string' && isValidIso(value) ? value : undefined;
}

// ----- public converters (exported from the entry point) -----

/** Reads the LOCAL calendar date off a `Date`. */
export function mudDateFromDate(date: Date): string {
  return toIso({ y: date.getFullYear(), m: date.getMonth() + 1, d: date.getDate() });
}

/**
 * Local **noon**, not midnight: a DST transition can move midnight across a
 * day boundary, noon cannot. `new Date('2026-08-27')` would parse as UTC and
 * reintroduce exactly the bug this library avoids.
 */
export function mudDateToDate(iso: string): Date {
  const date = parseIso(iso);

  if (!date) return new Date(NaN);

  return new Date(date.y, date.m - 1, date.d, 12, 0, 0, 0);
}

export function mudToday(): string {
  return mudDateFromDate(new Date());
}

export function mudAddDays(iso: string, amount: number): string {
  return addDays(iso, amount);
}

import { isValidIso, toIso } from './date-core';

export type MudDateFormat = 'DD/MM/YYYY' | 'MM/DD/YYYY' | 'YYYY-MM-DD';
export type MudDateSegmentKind = 'DD' | 'MM' | 'YYYY';

export interface MudDateSegment {
  kind: MudDateSegmentKind;
  /** Digit count: 2 for DD/MM, 4 for YYYY. */
  length: number;
  /** Offset of the segment's first digit within the display string. */
  start: number;
}

export interface MudDateFormatSpec {
  format: MudDateFormat;
  separator: string;
  segments: MudDateSegment[];
  /** Length of a fully-typed display value. */
  length: number;
}

const ORDERS: Record<MudDateFormat, { separator: string; kinds: MudDateSegmentKind[] }> = {
  'DD/MM/YYYY': { separator: '/', kinds: ['DD', 'MM', 'YYYY'] },
  'MM/DD/YYYY': { separator: '/', kinds: ['MM', 'DD', 'YYYY'] },
  'YYYY-MM-DD': { separator: '-', kinds: ['YYYY', 'MM', 'DD'] },
};

const specCache = new Map<MudDateFormat, MudDateFormatSpec>();

export function formatSpec(format: MudDateFormat): MudDateFormatSpec {
  const cached = specCache.get(format);

  if (cached) return cached;

  const { separator, kinds } = ORDERS[format];
  let start = 0;

  const segments = kinds.map((kind) => {
    const length = kind === 'YYYY' ? 4 : 2;
    const segment: MudDateSegment = { kind, length, start };

    start += length + 1;

    return segment;
  });

  const spec: MudDateFormatSpec = { format, separator, segments, length: format.length };

  specCache.set(format, spec);

  return spec;
}

function digitsOf(value: string): string {
  return value.replace(/\D/g, '');
}

/**
 * Strips everything that isn't a digit, then walks the segment spec inserting
 * the separator between segments. Typing `1504` yields `15/04`, so the
 * separator is never something the user has to press.
 *
 * The separator is LAZY — emitted only when a following digit exists — exactly
 * as `phone-input`'s `phone-mask` does it. Appending it the instant a segment
 * filled (`15` → `15/`) made the field un-deletable: Backspace removes the
 * `/`, the re-mask puts it straight back, and the user can never delete the
 * month, never the day, and never clear the field with Backspace at all.
 */
export function formatMasked(raw: string, spec: MudDateFormatSpec): string {
  const maxDigits = spec.segments.reduce((sum, segment) => sum + segment.length, 0);
  const digits = digitsOf(raw).slice(0, maxDigits);

  if (!digits) return '';

  let out = '';
  let next = 0;

  for (const segment of spec.segments) {
    const chunk = digits.slice(next, next + segment.length);

    if (!chunk) break;

    out += chunk;
    next += chunk.length;

    // Nothing typed past this segment yet, so there is no separator to write —
    // and the last segment can never have anything past it.
    if (next >= digits.length) break;

    out += spec.separator;
  }

  return out;
}

/** The untyped tail of the format pattern, rendered behind the caret. */
export function ghostRemainder(display: string, spec: MudDateFormatSpec): string {
  return spec.format.slice(display.length);
}

/** ISO string for a complete, real date; `null` while incomplete or impossible. */
export function displayToIso(display: string, spec: MudDateFormatSpec): string | null {
  if (display.length !== spec.length) return null;

  const part = (kind: MudDateSegmentKind): number => {
    const segment = spec.segments.find((candidate) => candidate.kind === kind)!;

    return Number(display.slice(segment.start, segment.start + segment.length));
  };

  const iso = toIso({ y: part('YYYY'), m: part('MM'), d: part('DD') });

  return isValidIso(iso) ? iso : null;
}

export function isoToDisplay(iso: string, spec: MudDateFormatSpec): string {
  if (!isValidIso(iso)) return '';

  const values: Record<MudDateSegmentKind, string> = {
    YYYY: iso.slice(0, 4),
    MM: iso.slice(5, 7),
    DD: iso.slice(8, 10),
  };

  return spec.segments.map((segment) => values[segment.kind]).join(spec.separator);
}

export function digitsBefore(value: string, caret: number): number {
  return digitsOf(value.slice(0, Math.max(0, caret))).length;
}

/**
 * Offset immediately after the nth digit, so a re-mask restores the caret to
 * the digit the user was working on instead of flinging it to the end.
 *
 * Task 14 needed an extra clause here — when the nth digit was the LAST one
 * typed and a just-auto-inserted separator followed it, the caret had to land
 * after that separator, or it would visibly stall one position short of where
 * forward typing continues. `formatMasked`'s separator is now lazy, so a
 * masked string always ENDS on a digit: for the last digit, `i + 1` is already
 * the end of the string and there is no separator left to step over. The
 * clause was removed with the bug that made it necessary.
 */
export function caretForDigitIndex(masked: string, digitIndex: number): number {
  if (digitIndex <= 0) return 0;

  let seen = 0;

  for (let i = 0; i < masked.length; i += 1) {
    if (!/\d/.test(masked[i])) continue;

    seen += 1;

    if (seen === digitIndex) return i + 1;
  }

  return masked.length;
}

import { computed, InjectionToken, isSignal } from '@angular/core';
import type { Provider, Signal } from '@angular/core';

/**
 * Every user-facing string the date components render. Defaults are English;
 * localize an entire app with one `provideMudDateLabels` call - pass a signal
 * (or a factory returning one) and the calendars re-render live when it
 * changes, so a runtime language switch needs no per-instance wiring.
 */
export interface MudDateLabels {
  /**
   * BCP 47 locale for `Intl`-derived month/weekday names, so one signal can
   * switch strings AND names together. Precedence: a component's own `locale`
   * input, then this, then the app `LOCALE_ID`.
   */
  locale?: string;

  /** Accessible name of the calendar popover dialog. */
  calendar: string;
  previousMonth: string;
  nextMonth: string;
  previousYear: string;
  nextYear: string;
  /** Header button that opens the month grid. */
  chooseMonth: string;
  /** Header button that opens the year grid. */
  chooseYear: string;
  /** "Today" quick-jump shortcut. */
  today: string;
  /** Clear (×) button. */
  clear: string;
  /** Accessible name of the range start field. */
  rangeStart: string;
  /** Accessible name of the range end field. */
  rangeEnd: string;
  /**
   * Twelve SHORT month names for the month-picker grid, January first
   * (`['Ian', 'Feb', …]`). If empty - derived from `Intl` for the active locale.
   */
  monthNamesShort?: readonly string[];

  /**
   * Twelve FULL month names, January first, the header title, the dropdown
   * chip, announcements, and the month buttons' accessible names. Unset:
   * derived from `Intl` for the active locale.
   */
  monthNamesLong?: readonly string[];

  /** Describes the expected entry format, e.g. "Date format: DD/MM/YYYY". */
  formatHint: (pattern: string) => string;
  /** Announced after the visible month changes. */
