@Component({
  selector: 'mud-table-story-selection',
  imports: [...TABLE_IMPORTS, MudCheckbox],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <table mud-table [dataSource]="rows" rowStyle="zebra" hoverable aria-label="Cereri de aprobat">
