            @if (page.isLoading()) {
              <mud-spinner size="small" aria-label="Se încarcă cererile" />
            } @else if (page.error()) {
              Nu am putut încărca cererile. Încearcă din nou.
            } @else {
              Nu există cereri depuse.
            }
          </td>
        </tr>
      </table>
    </div>
    <mud-pagination
      [length]="shown().total"
      [pageSize]="pageSize"
      [(pageIndex)]="pageIndex"
      [disabled]="page.isLoading()"
      style="justify-content: flex-end; margin-block-start: 16px"
    />
  `,
