  localitate: LOCALITATI[(i * 3 + Math.floor(i / NUME.length)) % LOCALITATI.length],
  depusa: ${BT}2026-0\${8 + (i % 2)}-\${String((i % 28) + 1).padStart(2, '0')}${BT},
  suma: ((i * 137) % 1900) + 50,
  stare: STARI[i % STARI.length],
}));`;

