import type { ComponentRef } from '@angular/core';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChildren,
  effect,
  ElementRef,
  inject,
  input,
  numberAttribute,
} from '@angular/core';
import { forwardCrumbClick } from './forward-crumb-click';
import { MudBreadcrumbItem } from './mud-breadcrumb-item.directive';
import { MudBreadcrumbOverflow } from './mud-breadcrumb-overflow.component';
import { MudStyleLoader } from 'ngx-mud-ui/core';
import { _MudBreadcrumbStyles } from './mud-breadcrumb-styles.component';

/** Below two crumbs there is no "first plus last two" to collapse into. */
const MIN_VISIBLE = 2;

const coerceMaxVisible = (value: unknown): number => {
  const parsed = numberAttribute(value, MIN_VISIBLE);

  if (!Number.isFinite(parsed) || parsed < MIN_VISIBLE) {
    if (typeof ngDevMode === 'undefined' || ngDevMode) {
      console.warn(
        `[mud-breadcrumb] maxVisible must be >= ${String(MIN_VISIBLE)} (got ${String(value)}). Coercing to ${String(MIN_VISIBLE)}.`,
      );
    }

    return MIN_VISIBLE;
  }

  return parsed;
};

/**
 * ```html
 * <nav mudBreadcrumb [maxVisible]="4">
 *   <ol>
 *     <li mudBreadcrumbItem><a routerLink="/">Acasă</a></li>
 *     <li mudBreadcrumbItem active><span>Cerere nouă</span></li>
 *   </ol>
 * </nav>
 * ```
 */
@Component({
  // eslint-disable-next-line @angular-eslint/component-selector
  selector: 'nav[mudBreadcrumb]',
  exportAs: 'mudBreadcrumb',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (_backTarget(); as target) {
      @if (target.href(); as href) {
        <a class="mud-breadcrumb__back" [attr.href]="href" (click)="_goBack($event, target)">
          <span class="mud-breadcrumb__back-icon" aria-hidden="true"></span>
          <span class="mud-breadcrumb__back-label">{{ target.text() }}</span>
        </a>
      } @else {
        <button type="button" class="mud-breadcrumb__back" (click)="_goBack($event, target)">
          <span class="mud-breadcrumb__back-icon" aria-hidden="true"></span>
          <span class="mud-breadcrumb__back-label">{{ target.text() }}</span>
        </button>
      }
    }

    <ng-content />
  `,
  host: {
    class: 'mud-breadcrumb',
    '[attr.aria-label]': '_ariaLabel()',
    '[class.mud-breadcrumb--collapsible]': '_backTarget() !== null',
  },
})
export class MudBreadcrumb {
  private readonly _element: HTMLElement = inject(ElementRef).nativeElement;
  // Read once at construction: a host binding would otherwise overwrite a
  // static aria-label the consumer wrote on the same element.
  private readonly _authoredAriaLabel = this._element.getAttribute('aria-label');

  /** @description Crumbs shown before the middle collapses into the overflow menu. */
  readonly maxVisible = input<number, unknown>(4, { transform: coerceMaxVisible });
  /** @description Accessible name for the navigation landmark. A consumer aria-label wins. */
  readonly label = input('Breadcrumb');
  /** @description Accessible name for the overflow trigger. */
  readonly overflowLabel = input('Show collapsed pages');
  /** @description When false, the trail never collapses to the mobile back link. */
  readonly responsive = input(true, { transform: booleanAttribute });

  // descendants: true is load-bearing — the default (false) only looks at the
  // host's immediate children, and every crumb is now one level down inside the
  // consumer's <ol>, so the query would silently come back empty.
  protected readonly _items = contentChildren(MudBreadcrumbItem, { descendants: true });

  protected readonly _ariaLabel = computed(() => this._authoredAriaLabel ?? this.label());

  /** Crumbs that live in the overflow panel: everything but the first and the last two. */
  protected readonly _collapsedItems = computed(() => {
    const items = this._items();

    return items.length > this.maxVisible() ? items.slice(1, -2) : [];
  });

  /** Explicit `active` wins; otherwise the last crumb that is navigable. */
  protected readonly _currentIndex = computed(() => {
    const items = this._items();
    const explicit = items.findIndex((item) => item.active());

    if (explicit !== -1) return explicit;

    for (let index = items.length - 1; index >= 0; index -= 1) {
      if (!items[index].disabled()) return index;
    }

    return items.length - 1;
  });

  /** The nearest navigable crumb above the current page — the only crumb mobile shows. */
  protected readonly _backTarget = computed(() => {
    if (!this.responsive()) return null;

    const items = this._items();

    if (items.length < 2) return null;

    for (let index = this._currentIndex() - 1; index >= 0; index -= 1) {
      const candidate = items[index];

      if (!candidate.disabled()) return candidate;
    }

    return null;
  });

  private _overflowRef: ComponentRef<MudBreadcrumbOverflow> | null = null;

  constructor() {
    inject(MudStyleLoader).load(_MudBreadcrumbStyles);

    effect(() => {
      const items = this._items();
      const collapsedItems = this._collapsedItems();
      const collapsed = new Set(collapsedItems);
      const currentIndex = this._currentIndex();

      items.forEach((item, index) => {
        item.setState({ collapsed: collapsed.has(item), current: index === currentIndex });
      });

      this._syncOverflow(items[0], collapsedItems);
    });
  }

  private _syncOverflow(
    owner: MudBreadcrumbItem | undefined,
    collapsed: readonly MudBreadcrumbItem[],
  ): void {
    if (collapsed.length === 0 || !owner) {
      this._overflowRef?.destroy();
      this._overflowRef = null;

      return;
    }

    if (!this._overflowRef) {
      this._overflowRef = owner.viewContainerRef.createComponent(MudBreadcrumbOverflow);
      this._overflowRef.onDestroy(() => {
        this._overflowRef = null;
      });
    }

    this._overflowRef.setInput('items', collapsed);
    this._overflowRef.setInput('label', this.overflowLabel());
  }

  protected _goBack(event: MouseEvent, target: MudBreadcrumbItem): void {
    forwardCrumbClick(event, target);
  }
}

import type { OverlayRef } from '@angular/cdk/overlay';
import { Overlay } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import type { OnDestroy, TemplateRef } from '@angular/core';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  inject,
  input,
  signal,
  viewChild,
  ViewContainerRef,
} from '@angular/core';
import { forwardCrumbClick } from './forward-crumb-click';
import type { MudBreadcrumbItem } from './mud-breadcrumb-item.directive';
import { _MudMenuStyles, MudStyleLoader } from 'ngx-mud-ui/core';
import { _MudBreadcrumbStyles } from './mud-breadcrumb-styles.component';

let nextUniqueId = 0;

/** The `…` disclosure that reveals the collapsed crumbs. Created by MudBreadcrumb. */
@Component({
  selector: 'mud-breadcrumb-overflow',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'mud-breadcrumb__overflow', role: 'listitem' },
  template: `
    <button
      type="button"
      class="mud-breadcrumb__overflow-trigger"
      [attr.aria-label]="label()"
      [attr.aria-expanded]="_open()"
      [attr.aria-controls]="_open() ? panelId : null"
      (click)="toggle()"
    >
      &hellip;
    </button>

    <ng-template #panel>
      <!-- The ul itself is never focused: focus always lives on one of its link/button
           children, which is what the roving arrow-key navigation moves between. -->
      <!-- eslint-disable-next-line @angular-eslint/template/interactive-supports-focus -->
      <ul class="menu mud-breadcrumb__panel" [id]="panelId" (keydown)="_onKeydown($event)">
        @for (crumb of items(); track crumb) {
          <li class="mud-breadcrumb__panel-row">
            @if (crumb.href(); as href) {
              <a
                class="menu__item mud-breadcrumb__panel-item"
                [attr.href]="href"
                (click)="_forward($event, crumb)"
                ><span class="menu__label">{{ crumb.text() }}</span></a
              >
            } @else {
              <button
                type="button"
                class="menu__item mud-breadcrumb__panel-item"
                (click)="_forward($event, crumb)"
              >
                <span class="menu__label">{{ crumb.text() }}</span>
              </button>
            }
          </li>
        }
      </ul>
    </ng-template>
  `,
})
export class MudBreadcrumbOverflow implements OnDestroy {
  private readonly _overlay = inject(Overlay);
  private readonly _viewContainerRef = inject(ViewContainerRef);
  private readonly _element: HTMLElement = inject(ElementRef).nativeElement;
  private readonly _panel = viewChild.required<TemplateRef<unknown>>('panel');
  private _overlayRef: OverlayRef | null = null;

  /** @description Crumbs the container collapsed out of the trail. */
  readonly items = input<readonly MudBreadcrumbItem[]>([]);
  /** @description Accessible name for the trigger. */
  readonly label = input('Show collapsed pages');

  readonly panelId = `mud-breadcrumb-panel-${String(nextUniqueId++)}`;

  protected readonly _open = signal(false);

  constructor() {
    const styles = inject(MudStyleLoader);

    styles.load(_MudBreadcrumbStyles);
    styles.load(_MudMenuStyles);
  }

  ngOnDestroy(): void {
    this._dispose();
  }

  toggle(): void {
    if (this._open()) {
      this.close(true);

      return;
    }

    this._attach();
  }

  /** Closes the panel; restoreFocus pulls focus back to the `…` trigger. */
  close(restoreFocus: boolean): void {
    if (!this._open()) return;

    this._dispose();
    this._open.set(false);

    if (restoreFocus) this._triggerElement()?.focus();
  }

  private _attach(): void {
    const overlayRef = this._overlay.create({
      positionStrategy: this._overlay
        .position()
        .flexibleConnectedTo(this._triggerElement() ?? this._element)
        .withPositions([
          { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 4 },
          { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -4 },
        ]),
      scrollStrategy: this._overlay.scrollStrategies.reposition(),
    });

    overlayRef.attach(new TemplatePortal(this._panel(), this._viewContainerRef));
    overlayRef.outsidePointerEvents().subscribe((event) => {
      if (this._triggerElement()?.contains(event.target as Node)) return;

      this.close(false);
    });

    this._overlayRef = overlayRef;
    this._open.set(true);
    this._links()[0]?.focus();
  }

  private _dispose(): void {
    this._overlayRef?.dispose();
    this._overlayRef = null;
  }

  private _triggerElement(): HTMLButtonElement | null {
    return this._element.querySelector<HTMLButtonElement>('.mud-breadcrumb__overflow-trigger');
  }

  private _links(): HTMLElement[] {
    const panel = this._overlayRef?.overlayElement;

    return panel ? [...panel.querySelectorAll<HTMLElement>('.mud-breadcrumb__panel-item')] : [];
  }

  protected _onKeydown(event: KeyboardEvent): void {
    const links = this._links();
    const index = links.indexOf(document.activeElement as HTMLElement);

    switch (event.key) {
      case 'Escape':
        event.preventDefault();
        this.close(true);

        return;
      case 'ArrowDown':
        event.preventDefault();
        links[(index + 1) % links.length]?.focus();

        return;
      case 'ArrowUp':
        event.preventDefault();
        links[index <= 0 ? links.length - 1 : index - 1]?.focus();

        return;
      case 'Home':
        event.preventDefault();
        links[0]?.focus();

        return;
      case 'End':
        event.preventDefault();
        links[links.length - 1]?.focus();

        return;
      case 'Tab':
        this.close(true);

        return;
      default:
        return;
    }
  }

  protected _forward(event: MouseEvent, crumb: MudBreadcrumbItem): void {
    forwardCrumbClick(event, crumb, () => this.close(false));
  }
}

