import {
  afterRenderEffect,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  contentChildren,
  forwardRef,
  inject,
  input,
  model,
  output,
  PLATFORM_ID,
  signal,
  viewChild,
} from '@angular/core';
import type { ElementRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import type { ControlValueAccessor } from '@angular/forms';
import type { FormCheckboxControl } from '@angular/forms/signals';
import { MudLabel } from 'ngx-mud-ui/label';
import { MudInlineMessage } from 'ngx-mud-ui/inline-message';
import { _MudSelectionControlStyles, MudStyleLoader } from 'ngx-mud-ui/core';

export type MudCheckboxSize = 'medium' | 'small';

let nextUniqueId = 0;

/**
 * ```html
 * <mud-checkbox [formField]="form.subscribed" required>
 *   <mud-label>Accept termenii</mud-label>
 *   @if (form.subscribed().touched() && form.subscribed().invalid()) {
 *     <mud-inline-message variant="error">Message.</mud-inline-message>
 *   }
 * </mud-checkbox>
 * ```
 */
@Component({
  selector: 'mud-checkbox',
  templateUrl: './mud-checkbox.component.html',
  host: {
    '[class]': '_hostClasses()',
  },
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MudCheckbox),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudCheckbox implements ControlValueAccessor, FormCheckboxControl {
  /** @description Size rung: medium (24px box) or small (20px). */
  readonly size = input<MudCheckboxSize>('medium');

  /** @description Checked state. Two-way bindable; also driven by both forms systems. */
  readonly checked = model(false);

  /**
   * @description Mixed state (the dash). Consumer-owned: rendering follows this input
   * only, and user toggles do not clear it — update it yourself on change.
   * Exposed to assistive tech via the native indeterminate property.
   */
  readonly indeterminate = input(false, { transform: booleanAttribute });

  readonly disabled = input(false, { transform: booleanAttribute });

  /** @description Adds the red asterisk and the native `required` attribute. */
  readonly required = input(false, { transform: booleanAttribute });

  /** @description Focusable and readable, but not toggleable. */
  readonly readonly = input(false, { transform: booleanAttribute });

  /** @description Destructive visuals + `aria-invalid`. Signal forms bind this automatically. */
  readonly invalid = input(false, { transform: booleanAttribute });

  readonly name = input<string>('');

  /** @description Accessible name when no visible label is rendered. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  /** @description External labelling element id(s); wins over `ariaLabel`. */
  readonly ariaLabelledby = input<string | undefined>(undefined, { alias: 'aria-labelledby' });

  /** @description Extra id(s) merged into the native control's aria-describedby. */
  readonly ariaDescribedby = input<string | undefined>(undefined, { alias: 'aria-describedby' });

  /** Signal-forms touch contract: emitted when focus leaves the control. */
  readonly touch = output<void>();

  private readonly _native = viewChild.required<ElementRef<HTMLInputElement>>('native');
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  /** @docs-private Projected label element (ngx-mud-ui/label). */
  protected readonly _label = contentChild(MudLabel);

  /** @docs-private Consumer-projected assistive messages. */
  private readonly _messages = contentChildren(MudInlineMessage);

  protected readonly _hasLabel = computed(() => !!this._label());

  protected readonly _hasMessages = computed(() => this._messages().length > 0);

  protected readonly _id = `mud-checkbox-${nextUniqueId++}`;
  protected readonly _assistiveId = `${this._id}-assistive`;

  private readonly _cvaDisabled = signal(false);
  private _onChange: (checked: boolean) => void = () => undefined;
  private _onTouched: () => void = () => undefined;

  /** @docs-private Input + forms-driven disabled state combined. */
  protected readonly _effectiveDisabled = computed(() => this.disabled() || this._cvaDisabled());

  protected readonly _effectiveInvalid = computed(() => this.invalid());

  protected readonly _describedBy = computed<string | null>(() => {
    const ids: string[] = [];

    if (this._hasMessages()) ids.push(this._assistiveId);

    const external = this.ariaDescribedby()?.trim();

    if (external) ids.push(external);

    return ids.length > 0 ? ids.join(' ') : null;
  });

  protected readonly _ariaLabel = computed<string | null>(() => {
    if (this.ariaLabelledby()) return null;

    if (this._hasLabel()) return null;

    return this.ariaLabel() ?? null;
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['selection-control'];

    if (this.size() === 'small') classes.push('selection-control--sm');

    if (this.checked()) classes.push('is-checked');

    if (this.indeterminate()) classes.push('is-indeterminate');

    if (this._effectiveDisabled()) classes.push('is-disabled');

    if (this.readonly()) classes.push('is-readonly');

    if (this._effectiveInvalid()) classes.push('is-invalid');

    return classes.join(' ');
  });

  constructor() {
    inject(MudStyleLoader).load(_MudSelectionControlStyles);

    // The mixed state only exists as a DOM property; mirror the input onto
    // the native control so assistive tech announces "mixed".
    afterRenderEffect(() => {
      this._native().nativeElement.indeterminate = this.indeterminate();
    });
  }

  // ----- ControlValueAccessor (reactive/template-driven forms) -----

  writeValue(value: boolean | null | undefined): void {
    this.checked.set(!!value);
  }

  registerOnChange(fn: (checked: boolean) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._cvaDisabled.set(isDisabled);
  }

  // ----- FormCheckboxControl extras -----

  /** Focuses the native checkbox (also used by signal forms' focus requests). */
  focus(options?: FocusOptions): void {
    if (!this._isBrowser) return;

    this._native().nativeElement.focus(options);
  }

  // ----- internal handlers -----

  protected _onClick(event: MouseEvent): void {
    // A native checkbox has no readonly; blocking click (which also carries
    // keyboard Space activation) emulates it while keeping focusability.
    if (this.readonly()) event.preventDefault();
  }

  protected _onNativeChange(event: Event): void {
    const next = (event.target as HTMLInputElement).checked;

    this.checked.set(next);
    this._onChange(next);
  }

  protected _onBlur(): void {
    this._onTouched();
    this.touch.emit();
  }
}

import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
  model,
  output,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { MudStyleLoader } from 'ngx-mud-ui/core';
import { _MudChipStyles } from './mud-chip-styles.component';

export type MudChipType = 'filter' | 'input';
export type MudChipSize = 'small' | 'medium';

/**
 * Selection behaviour for `type="filter"`:
 * - `mono` — single-choice (radio-like); the selected chip just flips color.
 * - `multi` — multi-choice (checkbox-like); a leading check appears when selected.
 */
export type MudChipSelectionMode = 'mono' | 'multi';

/**
 * Compact pill for filter selection or token display.
 *
 * - `type="filter"` (default): a toggle button — click flips `selected`
 *   (`aria-pressed` exposed). Mono-exclusivity across a group is
 *   consumer-owned via `selectedChange`.
 * - `type="input"`: a discrete user-entered value. The body is static (no
 *   dead tab stop); with `removable`, a trailing close button emits `removed`.
 *
 * ```html
 * <mud-chip selectionMode="multi" [(selected)]="active" [count]="12">Acte</mud-chip>
 * <mud-chip type="input" removable (removed)="drop(tag)">{{ tag }}</mud-chip>
 * ```
 */
@Component({
  selector: 'mud-chip',
  templateUrl: './mud-chip.component.html',
  imports: [NgTemplateOutlet],
  host: {
    '[class]': '_hostClasses()',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudChip {
  /** @description Behavioral mode: `filter` toggles on click, `input` is a static token. */
  readonly type = input<MudChipType>('filter');

  /** @description Size rung: medium (36px) or small (28px). */
  readonly size = input<MudChipSize>('medium');

  /** @description Selected state for `type="filter"`. Two-way bindable; ignored for `input`. */
  readonly selected = model(false);

  /** @description In `multi` mode a leading check renders automatically while selected. */
  readonly selectionMode = input<MudChipSelectionMode>('mono');

  /** @description Optional numeric badge after the label; its colors invert with the surface. */
  readonly count = input<number | undefined>(undefined);

  readonly disabled = input(false, { transform: booleanAttribute });

  /** @description For `type="input"`: renders the trailing close button that emits `removed`. */
  readonly removable = input(false, { transform: booleanAttribute });

  /**
   * @description ARIA-only fallback name (mud-button convention): applied as `aria-label`
   * when set, and appended to the remove button's accessible name. Visible
   * text belongs in the default content.
   */
  readonly label = input<string | undefined>(undefined);

  /** @description Accessible-label prefix of the remove button. Localize per app. */
  readonly removeLabel = input('Remove');

  /** Fired when the remove button of a removable `input` chip is activated. */
  readonly removed = output<void>();

  protected readonly _isFilter = computed(() => this.type() === 'filter');

  /**
   * @docs-private `model()` has no `booleanAttribute` transform, so a static
   * `selected` attribute delivers `''` — coerce it here (present = true) and
   * read only this everywhere (class, check, aria-pressed, toggle).
   */
  protected readonly _selected = computed(() => booleanAttribute(this.selected()));

  protected readonly _showRemove = computed(() => this.type() === 'input' && this.removable());

  protected readonly _showCheck = computed(
    () => this._isFilter() && this.selectionMode() === 'multi' && this._selected(),
  );

  protected readonly _showCount = computed(() => Number.isFinite(this.count()));

  protected readonly _removeAriaLabel = computed(() => {
    const label = this.label()?.trim();

    return label ? `${this.removeLabel()} ${label}` : this.removeLabel();
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['chip', `chip--${this.type()}`];

    if (this.size() === 'small') classes.push('chip--sm');

    if (this._isFilter() && this._selected()) classes.push('is-selected');

    if (this.disabled()) classes.push('is-disabled');

    if (this._showRemove()) classes.push('is-removable');

    if (this._showCheck()) classes.push('shows-check');

    return classes.join(' ');
  });

  constructor() {
    inject(MudStyleLoader).load(_MudChipStyles);
  }

  protected _toggle(): void {
    if (this.disabled() || !this._isFilter()) return;

    this.selected.set(!this._selected());
  }

  protected _onRemove(): void {
    if (this.disabled()) return;

    this.removed.emit();
  }
}

