@use '../../../src/lib/styles/abstracts/mixins/host';

@include host.typography('mud-date-picker');

.date-picker {
  background: var(--mud-color-background-base-default);
  border: var(--mud-border-width-1, 1px) solid var(--mud-color-border-base-default);
  border-radius: var(--mud-border-radius-12, 12px);
  box-sizing: border-box;
  color: var(--mud-color-text-base-default);
  display: flex;
  flex-direction: column;
  font-family: var(--mud-font-family-base);
  gap: var(--mud-spacing-8, 8px);
  padding: var(--mud-spacing-12, 12px);
  width: 320px;
}

.date-picker--elevated {
  box-shadow:
    var(
      --mud-drop-shadow-300,
      0 8px 12px 4px rgba(40, 46, 55, 0.06),
      0 2px 4px 0 rgba(40, 46, 55, 0.06)
    );
}

// `flat` sits inside a surface that already casts the shadow — the popover
// in mud-date-input, or a consumer's own card.
.date-picker--flat {
  box-shadow: none;
}

.date-picker.is-disabled {
  color: var(--mud-color-text-disabled-default);
  pointer-events: none;
}

.date-picker__header {
  align-items: center;
  display: flex;
  gap: var(--mud-spacing-8, 8px);
  justify-content: space-between;
  width: 100%;
}

.date-picker__nav {
  align-items: center;
  background: var(--mud-color-background-base-tertiary);
  border: 0;
  border-radius: var(--mud-border-radius-6, 6px);
  box-sizing: border-box;
  // base-default, not -secondary: upstream's nav icon is #121212 light / #fff
  // dark, which is what the default icon token resolves to.
  color: var(--mud-color-icon-base-default);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  height: 40px;
  justify-content: center;
  padding: 0;
  width: 40px;

  &:hover:not(:disabled) {
    background: var(--mud-color-background-base-tertiary-hover);
  }

  // Upstream: #B2B2B2 light / #616161 dark — the tertiary-active pair exactly.
  &:active:not(:disabled) {
    background: var(--mud-color-background-base-tertiary-active);
  }

  &:disabled {
    color: var(--mud-color-text-disabled-default);
    cursor: default;
  }

  svg {
    height: 20px;
    width: 20px;
  }
}

.date-picker__title,
.date-picker__chip {
  background: none;
  border: 0;
  border-radius: var(--mud-border-radius-6, 6px);
  color: inherit;
  cursor: pointer;
  font: inherit;
  // Pinned, not inherited: upstream's header title is 16/24 at 500 regardless
  // of the context the calendar is embedded in.
  font-size: 16px;
  font-weight: 500;
  // Figma: the header date matches the 40px nav arrows, not its text box.
  height: 40px;
  line-height: 24px;
  padding: 0 var(--mud-spacing-8, 8px);

  &:hover:not(:disabled) {
    background: var(--mud-color-background-base-secondary-hover);
  }

  &:disabled {
    cursor: default;
  }
}

.date-picker__title {
  flex: 1 1 auto;
  text-align: center;
}

.date-picker__header-dropdowns {
  display: flex;
  flex: 1 1 auto;
  gap: var(--mud-spacing-4, 4px);
  justify-content: center;
}

.date-picker__grid {
  border-collapse: collapse;
  table-layout: fixed;
  width: 100%;
}

// Upstream metrics: 32px row, 14/20 at 500, uppercase. The COLOR deliberately
// diverges: upstream's #757575 light / #B2B2B2 dark sit at the AA borderline,
// so these keep base-secondary like the rest of the library's secondary text.
.date-picker__day-label {
  color: var(--mud-color-text-base-secondary);
  font-size: 14px;
  font-weight: 500;
  height: 32px;
  line-height: 20px;
  text-align: center;
  text-transform: uppercase;
  vertical-align: middle;
}

.date-picker__day {
  padding: 0;
  text-align: center;
}

.date-picker__day-button {
  background: none;
  border: 0;
  border-radius: var(--mud-border-radius-6, 6px);
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  // 40px rows x 6 fixed weeks: the calendar never changes height, so a short
  // month cannot resize the popover under the pointer.
  height: 40px;
  width: 100%;

  &:focus-visible {
    outline: var(--mud-focus-ring-outer-width, 3px) solid
      var(--mud-focus-ring-outer-color, var(--mud-blue-sky-500));
    outline-offset: -2px;
  }

  &:disabled {
    color: var(--mud-color-text-disabled-default);
    cursor: default;
  }
}

.date-picker__day:not(.is-selected)
  .date-picker__day-button:hover:not(:disabled):not([aria-disabled='true']) {
  background: var(--mud-color-background-base-default-hover);
  color: var(--mud-color-text-base-default);
}

// `--mud-color-text-base-secondary` alone (no opacity) — halving it again with
// `opacity` compounds the two dimmings and drops below WCAG AA's 4.5:1 for
// this 16px/normal-weight text (axe `color-contrast`, task 14 audit: 3.54:1).
// These cells are ordinary enabled buttons (a real adjacent-month date one
// click away), not disabled controls, so the contrast requirement applies.
.date-picker__day.is-outside .date-picker__day-button {
  color: var(--mud-color-text-base-secondary);
}

// Ordered AFTER `.is-outside` deliberately: the two selectors tie on
// specificity, and an outside-month day that is ALSO unavailable must read as
// unavailable. A SELECTED out-of-range day is the deliberate exception — the
// `.is-selected` rule below is later still and keeps the brand fill, because
// dropping a consumer's value out of sight is the failure mode this library
// rejects (see `writeValue`).
.date-picker__day .date-picker__day-button[aria-disabled='true'] {
  color: var(--mud-color-text-disabled-default);
  cursor: default;
}

// Upstream's today cell is brand-COLOURED text inside a 1.5px brand ring
// (`--date-picker-day-cell-today-color/border-color`), not just the ring. Both
// tokens here resolve to upstream's exact pair in each theme.
.date-picker__day.is-today .date-picker__day-button {
  box-shadow: inset 0 0 0 1.5px var(--mud-color-border-brand-default);
  color: var(--mud-color-text-brand-default);
}

.date-picker__day.is-today:not(.is-selected)
  .date-picker__day-button:hover:not(:disabled):not([aria-disabled='true']) {
  background: var(--mud-color-background-brand-secondary);
  color: var(--mud-color-text-brand-on-secondary);
}

.date-picker__day.is-selected .date-picker__day-button,
.date-picker__day.is-range-start .date-picker__day-button,
.date-picker__day.is-range-end .date-picker__day-button {
  background: var(--mud-color-background-brand-default);
  color: var(--mud-color-text-base-inverse-on-color);
}

.date-picker__day.is-selected .date-picker__day-button:hover:not(:disabled) {
  background: var(--mud-color-background-brand-default-hover);
}

.date-picker__day.is-range-middle {
  background: var(--mud-color-background-brand-secondary);
}

.date-picker__day.is-range-middle .date-picker__day-button:not([aria-disabled='true']) {
  color: var(--mud-color-text-brand-on-secondary);
}

// The endpoint half-bars only exist once BOTH ends are set. `is-range-lone`
// marks a start with no end yet — it renders as a plain selected day, with no
// half-bar pointing into empty space.
.date-picker__day.is-range-start:not(.is-range-lone) {
  background: linear-gradient(to right, transparent 50%, var(--mud-color-background-brand-secondary) 50%);
}

.date-picker__day.is-range-end {
  background: linear-gradient(to left, transparent 50%, var(--mud-color-background-brand-secondary) 50%);
}

// A single-day range: both halves would cancel out, so paint neither.
.date-picker__day.is-range-start.is-range-end {
  background: none;
}

// Both pickers are upstream's 4x3 twelve-cell grid — months always, years
// because the page size is 12 (see YEAR_PAGE in date-grid.ts).
.date-picker__month-grid,
.date-picker__year-grid {
  display: grid;
  gap: var(--mud-spacing-8, 8px);
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.date-picker__month-button,
.date-picker__year-button {
  background: none;
  border: 0;
  border-radius: var(--mud-border-radius-8, 8px);
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  height: 40px;
  line-height: 20px;
  width: 100%;

  &:hover:not(:disabled) {
    background: var(--mud-color-background-base-default-hover);
  }

  &:focus-visible {
    outline: var(--mud-focus-ring-outer-width, 3px) solid
      var(--mud-focus-ring-outer-color, var(--mud-blue-sky-500));
    outline-offset: -2px;
  }
}

.date-picker__month.is-selected .date-picker__month-button,
.date-picker__year.is-selected .date-picker__year-button {
  background: var(--mud-color-background-brand-default);
  color: var(--mud-color-text-base-inverse-on-color);
}

.date-picker__footer {
  display: flex;
  justify-content: center;
}

.date-picker__today {
  background: none;
  border: 0;
  border-radius: var(--mud-border-radius-6, 6px);
  color: var(--mud-color-text-brand-default);
  cursor: pointer;
  font: inherit;
  font-weight: 500;
  padding: var(--mud-spacing-8, 8px) var(--mud-spacing-12, 12px);

  &:hover:not(:disabled) {
    background: var(--mud-color-background-brand-secondary);
    color: var(--mud-color-text-brand-on-secondary);
  }

  &:focus-visible {
    outline: var(--mud-focus-ring-outer-width, 3px) solid
      var(--mud-focus-ring-outer-color, var(--mud-blue-sky-500));
    outline-offset: 2px;
  }
}

