import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  contentChildren,
  effect,
  forwardRef,
  inject,
  input,
  model,
  output,
  PLATFORM_ID,
  signal,
  viewChild,
  viewChildren,
} from '@angular/core';

declare const ngDevMode: boolean | undefined;

import type { ElementRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import type { ControlValueAccessor } from '@angular/forms';
import type { FormValueControl } from '@angular/forms/signals';
import { MudLabel } from 'ngx-mud-ui/label';
import { MudInlineMessage } from 'ngx-mud-ui/inline-message';
import { _MudInputFieldStyles, MudStyleLoader } from 'ngx-mud-ui/core';

export type MudInputChipVariant = 'default' | 'destructive';
export type MudInputChipSize = 'medium' | 'large';
export type MudInputChipErrorCode = 'pattern' | 'duplicate' | 'max';

export interface MudInputChipAdd {
  chip: string;
  chips: readonly string[];
}

export interface MudInputChipRemove {
  chip: string;
  index: number;
  chips: readonly string[];
}

export interface MudInputChipError {
  code: MudInputChipErrorCode;
  value: string;
}

let nextUniqueId = 0;

/**
 * ```html
 * <mud-input-chip [maxChips]="5" [validatePattern]="emailPattern" [formControl]="recipients">
 *   <mud-label>Destinatari</mud-label>
 *   @if (recipients.touched && recipients.invalid) {
 *     <mud-inline-message variant="error">Adăugați cel puțin o adresă.</mud-inline-message>
 *   }
 * </mud-input-chip>
 * ```
 */
@Component({
  selector: 'mud-input-chip',
  templateUrl: './mud-input-chip.component.html',
  host: {
    '[class]': '_hostClasses()',
  },
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MudInputChip),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudInputChip implements ControlValueAccessor, FormValueControl<string[]> {
  /** @description Color treatment. `destructive` is forced when `invalid` is set. */
  readonly variant = input<MudInputChipVariant>('default');

  /** @description Size rung: medium (40px min-height) or large (48px). */
  readonly size = input<MudInputChipSize>('medium');

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });
  readonly readonly = input(false, { transform: booleanAttribute });

  /** @description Destructive visuals + `aria-invalid`. Signal forms bind this automatically. */
  readonly invalid = input(false, { transform: booleanAttribute });

  /** @description Confirmed chips — the form value. Two-way bindable; driven by both forms systems. */
  readonly value = model<string[]>([]);

  /** @description The not-yet-confirmed text in the inline input. */
  readonly draft = model('');

  /** @description Maximum chips accepted; further additions emit `errored` with code `max`. */
  readonly maxChips = input<number | undefined>(undefined);

  /**
   * @description Values that don't match are rejected with code `pattern`.
   * Deliberately not named `pattern`: signal forms auto-bind that member with
   * an incompatible protocol (readonly RegExp[] of the field's own validators).
   */
  readonly validatePattern = input<RegExp | undefined>(undefined);

  /** @description Characters that confirm a chip in addition to Enter. Newlines always split pastes. */
  readonly separators = input(',');

  readonly name = input<string>('');

  /** @description Shown only while no chips exist. */
  readonly placeholder = input<string | undefined>(undefined);

  /** @description Accessible-label prefix of each chip's remove button. Localize per app. */
  readonly removeLabel = input('Remove');

  /** @description Builds the live-region announcement for an added chip. Localize per app. */
  readonly announceAdded = input<(chip: string) => string>((chip) => `${chip} added`);

  /** @description Builds the live-region announcement for a removed chip. Localize per app. */
  readonly announceRemoved = input<(chip: string) => string>((chip) => `${chip} removed`);

  /** @description Builds the live-region announcement for a rejected value. Localize per app. */
  readonly announceRejected = input<(error: MudInputChipError) => string>((error) => {
    switch (error.code) {
      case 'pattern':
        return `${error.value} is not in the expected format`;
      case 'duplicate':
        return `${error.value} is already added`;
      case 'max':
        return 'Maximum number of values reached';
    }
  });

  /** @description Accessible name used when no visible `label` is set. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  /** @description Extra id(s) merged into the native control's aria-describedby. */
  readonly ariaDescribedby = input<string | undefined>(undefined, { alias: 'aria-describedby' });

  /** Fired when a chip is confirmed. */
  readonly chipAdded = output<MudInputChipAdd>();

  /** Fired when a chip is removed. */
  readonly chipRemoved = output<MudInputChipRemove>();

  /** Fired for every rejected value (pattern / duplicate / max). */
  readonly errored = output<MudInputChipError>();

  /** Signal-forms touch contract: emitted when focus leaves the inline input. */
  readonly touch = output<void>();

  private readonly _native = viewChild.required<ElementRef<HTMLInputElement>>('native');
  private readonly _removeButtons = viewChildren<ElementRef<HTMLButtonElement>>('removeBtn');
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  /** @docs-private Projected label element (ngx-mud-ui/label). */
  protected readonly _label = contentChild(MudLabel);

  /** @docs-private Consumer-projected assistive messages. */
  private readonly _messages = contentChildren(MudInlineMessage);

  protected readonly _hasLabel = computed(() => !!this._label());

  protected readonly _hasMessages = computed(() => this._messages().length > 0);

  protected readonly _id = `mud-input-chip-${nextUniqueId++}`;
  protected readonly _labelId = `${this._id}-label`;
  protected readonly _assistiveId = `${this._id}-assistive`;

  protected readonly _focused = signal(false);

  /** @docs-private role=status live text announcing add / remove / reject. */
  protected readonly _announcement = signal('');

  private readonly _cvaDisabled = signal(false);
  private _onChange: (value: string[]) => void = () => undefined;
  private _onTouched: () => void = () => undefined;

  /** @docs-private Input + forms-driven disabled state combined. */
  protected readonly _effectiveDisabled = computed(() => this.disabled() || this._cvaDisabled());

  protected readonly _effectiveInvalid = computed(() => this.invalid());

  protected readonly _effectiveVariant = computed<MudInputChipVariant>(() =>
    this._effectiveInvalid() ? 'destructive' : this.variant(),
  );

  protected readonly _maxReached = computed(() => {
    const max = this.maxChips();

    return max !== undefined && this.value().length >= max;
  });

  /**
   * @docs-private The input locks at max only once the draft is empty: a
   * leftover draft (typed before a paste filled the last slots) must stay
   * editable, or readOnly would trap it.
   */
  protected readonly _effectiveReadonly = computed(
    () => this.readonly() || (this._maxReached() && this.draft().length === 0),
  );

  protected readonly _describedBy = computed<string | null>(() => {
    const ids: string[] = [];

    if (this._hasMessages()) ids.push(this._assistiveId);

    const external = this.ariaDescribedby()?.trim();

    if (external) ids.push(external);

    return ids.length > 0 ? ids.join(' ') : null;
  });

  protected readonly _ariaLabel = computed<string | null>(() => {
    if (this._hasLabel()) return null;

    return this.ariaLabel() ?? null;
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['input-field', 'chip-field', `input-field--${this._effectiveVariant()}`];

    if (this.size() === 'large') classes.push('input-field--lg');

    if (this._effectiveDisabled()) classes.push('is-disabled');

    if (this.readonly()) classes.push('is-readonly');

    if (this._effectiveInvalid()) classes.push('is-invalid');

    if (this._focused() && !this._effectiveDisabled()) classes.push('is-focused');

    return classes.join(' ');
  });

  constructor() {
    inject(MudStyleLoader).load(_MudInputFieldStyles);

    effect(() => {
      if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

      const max = this.maxChips();
      const count = this.value().length;

      if (max !== undefined && count > max) {
        console.warn(
          `[mud-input-chip] the bound value holds ${count} chips but maxChips is ${max}, ` +
            `so the field is read-only until enough are removed. ` +
            `Validation applies to typed input, not to the bound value.`,
        );
      }
    });
  }

  writeValue(value: readonly string[] | null | undefined): void {
    this.value.set(value ? [...value] : []);
  }

  registerOnChange(fn: (value: string[]) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._cvaDisabled.set(isDisabled);
  }

  /** @description Focuses the inline input (also used by signal forms' focus requests). */
  focus(options?: FocusOptions): void {
    if (!this._isBrowser) return;

    this._native().nativeElement.focus(options);
  }

  /**
   * A repeated message (same value rejected twice) would leave the live
   * region's DOM unchanged and never re-announce — alternate a trailing
   * zero-width space to force a mutation screen readers pick up.
   */
  private _announce(message: string): void {
    this._announcement.set(this._announcement() === message ? `${message}\u200B` : message);
  }

  // ----- chip mutations -----

  private _validateChip(value: string): MudInputChipErrorCode | null {
    if (this._maxReached()) return 'max';

    if (this.value().includes(value)) return 'duplicate';

    const pattern = this.validatePattern();

    if (pattern) {
      // A /g or /y regex is stateful across .test() calls; reset it so a
      // consumer-supplied global flag can't make validation alternate.
      pattern.lastIndex = 0;

      if (!pattern.test(value)) return 'pattern';
    }

    return null;
  }

  private _addChip(raw: string): boolean {
    const trimmed = raw.trim();

    if (!trimmed) return false;

    const code = this._validateChip(trimmed);

    if (code) {
      const error: MudInputChipError = { code, value: trimmed };

      this.errored.emit(error);
      this._announce(this.announceRejected()(error));

      return false;
    }

    const next = [...this.value(), trimmed];

    this.value.set(next);
    this._onChange(next);
    this.draft.set('');
    this._announce(this.announceAdded()(trimmed));
    this.chipAdded.emit({ chip: trimmed, chips: next });

    return true;
  }

  private _removeChip(index: number): void {
    const chip = this.value()[index];

    if (chip === undefined) return;

    const next = this.value().filter((_, i) => i !== index);

    this.value.set(next);
    this._onChange(next);
    this._announce(this.announceRemoved()(chip));
    this.chipRemoved.emit({ chip, index, chips: next });

    // Keyboard removals need focus to land somewhere predictable: the chip
    // now occupying this index, the new last chip, or back on the input.
    // @for tracks by $index, so the target button node already exists.
    if (next.length === 0) {
      this.focus();
    } else {
      this._focusChipAt(Math.min(index, next.length - 1));
    }
  }

  private _focusChipAt(index: number): void {
    this._removeButtons()[index]?.nativeElement.focus();
  }

  private _splitOnSeparators(raw: string): string[] {
    const escaped = this.separators()
      .split('')
      .map((sep) => sep.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
    const pattern = new RegExp(['\\n', ...escaped].join('|'));

    return raw
      .split(pattern)
      .map((token) => token.trim())
      .filter(Boolean);
  }

  protected _onDraftInput(event: Event): void {
    this.draft.set((event.target as HTMLInputElement).value);
  }

  protected _onInputKeydown(event: KeyboardEvent): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    if (event.key === 'Enter') {
      event.preventDefault();
      this._addChip(this.draft());

      return;
    }

    if (event.key === 'Escape') {
      // Only swallow Escape while it has a draft to clear; otherwise it
      // stays free for consumers (dialogs, overlays).
      if (this.draft().length > 0) {
        event.preventDefault();
        this.draft.set('');
      }

      return;
    }

    if (event.key === 'Backspace' && this.draft().length === 0 && this.value().length > 0) {
      event.preventDefault();
      this._removeChip(this.value().length - 1);

      return;
    }

    if (event.key === 'ArrowLeft' && this.draft().length === 0 && this.value().length > 0) {
      event.preventDefault();
      this._focusChipAt(this.value().length - 1);

      return;
    }

    if (this.separators().includes(event.key)) {
      event.preventDefault();
      this._addChip(this.draft());
    }
  }

  protected _onPaste(event: ClipboardEvent): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    const text = event.clipboardData?.getData('text') ?? '';

    if (!text) return;

    const tokens = this._splitOnSeparators(text);
    const hasSeparator =
      /\n/.test(text) ||
      this.separators()
        .split('')
        .some((sep) => text.includes(sep));

    // A single token without separators behaves like normal typing.
    if (tokens.length <= 1 && !hasSeparator) return;

    event.preventDefault();

    for (const token of tokens) {
      this._addChip(token);

      if (this._maxReached()) break;
    }
  }

  protected _onChipKeydown(event: KeyboardEvent, index: number): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    switch (event.key) {
      case 'Delete':
      case 'Backspace':
      case 'Enter':
      case ' ':
        event.preventDefault();
        this._removeChip(index);

        return;
      case 'ArrowLeft':
        if (index > 0) {
          event.preventDefault();
          this._focusChipAt(index - 1);
        }

        return;
      case 'ArrowRight':
        event.preventDefault();

        if (index < this.value().length - 1) this._focusChipAt(index + 1);
        else this.focus();

        return;
      case 'Escape':
        event.preventDefault();
        this.focus();
    }
  }

  protected _onRemoveClick(event: MouseEvent, index: number): void {
    event.stopPropagation();

    if (this._effectiveDisabled() || this.readonly()) return;

    this._removeChip(index);
  }

  protected _onControlClick(event: MouseEvent): void {
    if (this._effectiveDisabled()) return;

    const target = event.target as Element | null;

    if (target?.closest('.chip-field__chip')) return;

    this.focus();
  }

  protected _onFocus(): void {
    this._focused.set(true);
  }

  protected _onBlur(): void {
    this._focused.set(false);
    this._onTouched();
    this.touch.emit();
  }
}

import { ChangeDetectionStrategy, Component } from '@angular/core';

/**
 * ```html
 * <mud-text-input [formField]="form.idnp" required>
 *   <mud-label>IDNP <mud-icon name="circle-info" /></mud-label>
 * </mud-text-input>
 * ```
 */
@Component({
  selector: 'mud-label',
  template: `<ng-content />`,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudLabel {}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  DestroyRef,
  inject,
  input,
  output,
  signal,
  viewChild,
  ViewContainerRef,
} from '@angular/core';
import type { TemplateRef } from '@angular/core';

import { MUD_MEGA_MENU } from './mud-mega-menu.types';
import type { MudMegaMenuPanel, MudMegaMenuTriggerHandle } from './mud-mega-menu.types';
import { MudStyleLoader } from 'ngx-mud-ui/core';
import { _MudMegaMenuStyles } from './mud-mega-menu-styles.component';

let nextUniqueId = 0;

/**
 * ```html
 * <button [mudMegaMenuTriggerFor]="services">Servicii</button>
 * <mud-mega-menu #services>
 *   <mud-mega-menu-column heading="Plăți"><a mudMegaMenuLink href="/mpay">MPay</a></mud-mega-menu-column>
 * </mud-mega-menu>
 * ```
 */
@Component({
  selector: 'mud-mega-menu',
  template: `
    <ng-template #panelTpl>
      <nav
        class="mega-menu"
        [class]="panelClass() ?? ''"
        tabindex="-1"
        [id]="_panelId"
        [attr.aria-label]="_label() || null"
        [attr.aria-labelledby]="_label() ? null : _triggerId() || null"
        (keydown)="_onKeydown($event)"
      >
        <div class="mega-menu__columns"><ng-content /></div>
      </nav>
    </ng-template>
  `,
  providers: [{ provide: MUD_MEGA_MENU, useExisting: MudMegaMenu }],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudMegaMenu implements MudMegaMenuPanel {
  /** @description Accessible name for the panel; overrides the name taken from the button. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  /** @description Extra classes for the panel root. */
  readonly panelClass = input<string | string[] | undefined>(undefined);

  /** @description Close request raised inside the panel (Escape, link activation, Tab past the last link). */
  readonly closed = output<void>();

  /** @docs-private */
  readonly _panelId = `mud-mega-menu-panel-${nextUniqueId++}`;

  /** @docs-private Trigger attaches this template to its overlay. */
  readonly _panelTemplate = viewChild.required<TemplateRef<unknown>>('panelTpl');

  /** @docs-private */
  readonly _viewContainerRef = inject(ViewContainerRef);

  /** @docs-private The trigger currently presenting this panel, if any. */
  readonly _attachedTrigger = signal<MudMegaMenuTriggerHandle | null>(null);

  /** @docs-private Id of the presenting trigger; names the panel via aria-labelledby. */
  readonly _triggerId = signal('');

  protected readonly _label = computed(() => this.ariaLabel()?.trim() || '');

  private _linkCloseTimer: ReturnType<typeof setTimeout> | undefined;

  constructor() {
    inject(MudStyleLoader).load(_MudMegaMenuStyles);

    // Menu torn down while open: close so the trigger doesn't keep a stale aria-expanded.
    inject(DestroyRef).onDestroy(() => {
      clearTimeout(this._linkCloseTimer);
      this._attachedTrigger()?.close(false);
    });
  }

  /** @docs-private Deferred so routerLink / native navigation see the click first. */
  _linkActivated(): void {
    clearTimeout(this._linkCloseTimer);
    this._linkCloseTimer = setTimeout(() => {
      if (this._attachedTrigger()) this._requestClose(false);
    }, 0);
  }

  /** @docs-private */
  _requestClose(restoreFocus: boolean): void {
    this.closed.emit();
    this._attachedTrigger()?.close(restoreFocus);
  }

  protected _onKeydown(event: KeyboardEvent): void {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      this._requestClose(true);

      return;
    }

    if (event.key !== 'Tab') return;

    const links = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('.mega-menu__link'));
    const index = links.indexOf(event.target as HTMLElement);

    if (!event.shiftKey && index >= 0 && index === links.length - 1) {
      this._requestClose(true);
    } else if (event.shiftKey && index === 0) {
      event.preventDefault();
      this._attachedTrigger()?._hostElement.focus();
    }
  }
}

import { ChangeDetectionStrategy, Component, input } from '@angular/core';

/**
 * ```html
 * <mud-mega-menu-column heading="Servicii">
 *   <a mudMegaMenuLink href="/a">Option</a>
 * </mud-mega-menu-column>
 * ```
 */
@Component({
  selector: 'mud-mega-menu-column',
  template: `
    <h3 class="mega-menu__heading">{{ heading() }}</h3>
    <div class="mega-menu__separator" aria-hidden="true"></div>
    <div class="mega-menu__links"><ng-content /></div>
  `,
  host: { class: 'mega-menu__column' },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudMegaMenuColumn {
  /** @description Column heading, rendered as an h3 above the links. */
  readonly heading = input.required<string>();
}

import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  ElementRef,
  inject,
  Injector,
  input,
  output,
  PLATFORM_ID,
  signal,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { Overlay } from '@angular/cdk/overlay';
import type { GlobalPositionStrategy, OverlayRef, PositionStrategy } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import type { Subscription } from 'rxjs';

import type { MudMegaMenu } from './mud-mega-menu.component';
import { MudMegaMenuOrigin } from './mud-mega-menu-origin.directive';
import type { MudMegaMenuTriggerHandle } from './mud-mega-menu.types';
import { MudStyleLoader } from 'ngx-mud-ui/core';
import { _MudMegaMenuStyles } from './mud-mega-menu-styles.component';

let nextTriggerId = 0;

/**
 * ```html
 * <header mudMegaMenuOrigin>
 *   <button [mudMegaMenuTriggerFor]="services">Servicii</button>
 * </header>
 * ```
 */
@Component({
  // eslint-disable-next-line @angular-eslint/component-selector
  selector: 'button[mudMegaMenuTriggerFor]',
  template: `
    <span class="mega-menu-trigger__label"><ng-content /></span>
    <svg class="mega-menu-trigger__chevron" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" focusable="false">
      <path
        fill-rule="evenodd"
        clip-rule="evenodd"
        d="M4.47 6.47a.75.75 0 0 1 1.06 0L8 8.94l2.47-2.47a.75.75 0 1 1 1.06 1.06l-3 3a.75.75 0 0 1-1.06 0l-3-3a.75.75 0 0 1 0-1.06"
      />
    </svg>
  `,
  host: {
    class: 'mega-menu-trigger',
    type: 'button',
    '[class.is-open]': '_isOpen()',
    '[attr.aria-expanded]': '_isOpen()',
    '[attr.aria-controls]': '_isOpen() && _attachedMenu ? _attachedMenu._panelId : null',
    '(click)': 'toggle()',
    '(keydown)': '_onKeydown($event)',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudMegaMenuTrigger implements MudMegaMenuTriggerHandle {
  /** @description The mud-mega-menu this button presents. */
  readonly menu = input.required<MudMegaMenu>({ alias: 'mudMegaMenuTriggerFor' });

  /** @description Fired when the panel actually opens. */
  readonly opened = output<void>();

  /** @description Fired when the panel actually closes. */
  readonly closed = output<void>();

  private readonly _overlay = inject(Overlay);
  private readonly _host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _injector = inject(Injector);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
  private readonly _origin = inject(MudMegaMenuOrigin, { optional: true });

  /** @docs-private */
  readonly _hostElement = this._host.nativeElement;

  /** @docs-private */
  readonly _isOpen = signal(false);

  /** @docs-private The menu this open panel belongs to (the binding may switch while open). */
  _attachedMenu: MudMegaMenu | null = null;

  private _overlayRef: OverlayRef | null = null;
  private _outsideSub: Subscription | null = null;
  private _resizeObserver: ResizeObserver | null = null;
  private _globalStrategy: GlobalPositionStrategy | null = null;
  private _destroyed = false;

  constructor() {
    inject(MudStyleLoader).load(_MudMegaMenuStyles);

    inject(DestroyRef).onDestroy(() => {
      this._destroyed = true;
      this.close(false);
    });
  }

  /** Opens the panel (no-op on the server or when already open); closes a sibling sharing the origin. */
  open(): void {
    if (!this._isBrowser || this._destroyed || this._isOpen()) return;

    const menu = this.menu();

    if (!menu) return;

    const holder = menu._attachedTrigger();

    if (holder && holder !== this) holder.close(false);

    const origin = this._origin;

    if (origin?._openTrigger && origin._openTrigger !== this) origin._openTrigger.close(false);

    const overlayRef = this._overlay.create({
      positionStrategy: this._positionStrategy(),
      scrollStrategy: this._overlay.scrollStrategies.reposition(),
      ...this._paneSize(),
    });

    this._overlayRef = overlayRef;
    this._attachedMenu = menu;
    menu._attachedTrigger.set(this);

    const host = this._hostElement;

    if (!host.id) host.id = `mud-mega-menu-trigger-${nextTriggerId++}`;

    menu._triggerId.set(host.id);
    overlayRef.attach(new TemplatePortal(menu._panelTemplate(), menu._viewContainerRef));

    if (origin) origin._openTrigger = this;

    this._outsideSub = overlayRef.outsidePointerEvents().subscribe((event) => {
      const target = event.target as Node | null;

      if (target && this._hostElement.contains(target)) return;

      this.close(false);
    });

    this._watchSize();
    this._isOpen.set(true);
    this.opened.emit();
  }

  /** Closes the panel; restoreFocus returns focus to the button. */
  close(restoreFocus: boolean): void {
    if (!this._isOpen()) return;

    this._outsideSub?.unsubscribe();
    this._outsideSub = null;
    this._resizeObserver?.disconnect();
    this._resizeObserver = null;
    window.removeEventListener('resize', this._refit);
    window.removeEventListener('scroll', this._refit, { capture: true });
    this._overlayRef?.dispose();
    this._overlayRef = null;
    this._globalStrategy = null;
    this._attachedMenu?._attachedTrigger.set(null);
    this._attachedMenu = null;

    if (this._origin?._openTrigger === this) this._origin._openTrigger = null;

    this._isOpen.set(false);

    if (restoreFocus) this._hostElement.focus();

    if (!this._destroyed) this.closed.emit();
  }

  /** Toggles between open and closed. */
  toggle(): void {
    if (this._isOpen()) this.close(true);
    else this.open();
  }

  protected _onKeydown(event: KeyboardEvent): void {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this.open();
        afterNextRender(() => this._focusFirstLink(), { injector: this._injector });
        break;
      case 'Escape':
        if (this._isOpen()) {
          event.preventDefault();
          this.close(true);
        }

        break;
      case 'Tab':
        if (!this._isOpen()) return;

        if (event.shiftKey) {
          this.close(false);
        } else {
          if (this._focusFirstLink()) event.preventDefault();
        }

        break;
    }
  }

  private _focusFirstLink(): boolean {
    const link = this._overlayRef?.overlayElement.querySelector<HTMLElement>('.mega-menu__link');

    link?.focus();

    return !!link && document.activeElement === link;
  }

  private _positionStrategy(): PositionStrategy {
    if (this._origin) {
      return this._overlay
        .position()
        .flexibleConnectedTo(this._origin._element)
        .withFlexibleDimensions(true)
        .withPush(false)
        .withPositions([{ originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top' }]);
    }

    const rect = this._hostElement.getBoundingClientRect();

    this._globalStrategy = this._overlay.position().global().left('0').top(`${rect.bottom}px`);

    return this._globalStrategy;
  }

  private _paneSize(): { width: number | string; maxHeight?: number } {
    if (this._origin) return { width: this._origin._element.nativeElement.getBoundingClientRect().width };

    return { width: '100vw', maxHeight: Math.max(0, window.innerHeight - this._hostElement.getBoundingClientRect().bottom) };
  }

  private _watchSize(): void {
    if (this._origin) {
      if (typeof ResizeObserver === 'undefined') return;

      this._resizeObserver = new ResizeObserver(() => this._refit());
      this._resizeObserver.observe(this._origin._element.nativeElement);
    } else {
      window.addEventListener('resize', this._refit);
      window.addEventListener('scroll', this._refit, { capture: true, passive: true });
    }
  }

  private readonly _refit = (): void => {
    const overlayRef = this._overlayRef;

    if (!overlayRef) return;

    if (this._globalStrategy) {
      const rect = this._hostElement.getBoundingClientRect();

      this._globalStrategy.top(`${rect.bottom}px`);
      overlayRef.updateSize({ width: '100vw', maxHeight: Math.max(0, window.innerHeight - rect.bottom) });
    } else {
      overlayRef.updateSize(this._paneSize());
    }

    overlayRef.updatePosition();
  };
}

import {
  afterRenderEffect,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
  model,
  output,
  signal,
  viewChild,
  ViewContainerRef,
} from '@angular/core';
import type { TemplateRef } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';

import { MUD_MENU_PANEL } from './mud-menu.types';
import type {
  MudMenuPanel,
  MudMenuPositionX,
  MudMenuPositionY,
  MudMenuTriggerHandle,
  MudMenuType,
} from './mud-menu.types';
import type { MudMenuItem } from './mud-menu-item.component';
import { _MudMenuStyles, MudStyleLoader } from 'ngx-mud-ui/core';

let nextUniqueId = 0;

/**
 * ```html
 * <button mudButton [mudMenuTriggerFor]="actions">Actions</button>
 * <mud-menu #actions aria-label="Actions">
 *   <mud-menu-item value="edit">Edit</mud-menu-item>
 * </mud-menu>
 * ```
 */
@Component({
  selector: 'mud-menu',
  templateUrl: './mud-menu.component.html',
  imports: [NgTemplateOutlet],
  providers: [{ provide: MUD_MENU_PANEL, useExisting: MudMenu }],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudMenu implements MudMenuPanel {
  /** @description Menu semantics: `contextual` (ARIA menu) or `selection` (single-select listbox). */
  readonly type = input<MudMenuType>('contextual');

  /** @description Selected value (selection menus). Two-way bindable. */
  readonly value = model<string | undefined>(undefined);

  /** @description Horizontal placement relative to the trigger. */
  readonly xPosition = input<MudMenuPositionX>('after');

  /** @description Vertical placement relative to the trigger. */
  readonly yPosition = input<MudMenuPositionY>('below');

  /** @description Request a close right after an item is activated. */
  readonly closeOnSelect = input(true, { transform: booleanAttribute });

  /** @description Standalone mode only: render the panel in place. Ignored while a trigger is attached. */
  readonly open = input(false, { transform: booleanAttribute });

  /** @description Accessible name for the panel. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  /** @description Extra classes for the panel root, e.g. a component-specific modifier. */
  readonly panelClass = input<string | string[] | undefined>(undefined);

  /** @description Fired when any item is activated, with the item value ('' when it has none). */
  readonly selected = output<string>();

  /** @description Close request (Escape, Tab, closeOnSelect). With a trigger attached, listen on the trigger instead. */
  readonly closed = output<void>();

  /** @docs-private */
  readonly _panelId = `mud-menu-panel-${nextUniqueId++}`;

  /** @docs-private Trigger attaches this template to its overlay. */
  readonly _panelTemplate = viewChild.required<TemplateRef<unknown>>('panelTpl');

  /** @docs-private */
  readonly _viewContainerRef = inject(ViewContainerRef);

  /** @docs-private The trigger currently presenting this panel, if any. */
  readonly _attachedTrigger = signal<MudMenuTriggerHandle | null>(null);

  private readonly _items = signal<readonly MudMenuItem[]>([]);
  private readonly _active = signal<MudMenuItem | null>(null);

  protected readonly _renderInline = computed(() => this.open() && !this._attachedTrigger());

  private readonly _ordered = computed(() => {
    this.open();
    this._attachedTrigger();

    return [...this._items()].sort((a, b) =>
      a._host.nativeElement.compareDocumentPosition(b._host.nativeElement) & Node.DOCUMENT_POSITION_FOLLOWING
        ? -1
        : 1,
    );
  });

  private readonly _focusable = computed(() => this._ordered().filter((item) => !item.heading()));

  constructor() {
    inject(MudStyleLoader).load(_MudMenuStyles);

    afterRenderEffect(() => {
      const focusable = this._focusable();
      const active = this._active();
      const stop = active && focusable.includes(active) ? active : (focusable[0] ?? null);

      for (const item of this._focusable()) item._tabStop.set(item === stop);
    });
  }

  _register(item: MudMenuItem): void {
    this._items.update((items) => [...items, item]);
  }

  _unregister(item: MudMenuItem): void {
    this._items.update((items) => items.filter((candidate) => candidate !== item));

    if (this._active() === item) this._active.set(null);
  }

  _activate(item: MudMenuItem): void {
    if (item._hasSubmenu()) return;

    const value = item.value();

    if (this.type() === 'selection' && value !== undefined && this.value() !== value) {
      this.value.set(value);
    }

    this.selected.emit(value ?? '');

    if (this.closeOnSelect()) {
      this.closed.emit();
      this._attachedTrigger()?.closeAll(true);
    }
  }

  /** @docs-private Hover coordination; submenu sibling-closing arrives with the trigger. */
  _itemEntered(item: MudMenuItem): void {
    const child = this._attachedTrigger()?._childTrigger;

    if (child && child._hostItem !== item) child._scheduleClose();
  }

  _focusFirst(): void {
    this._focusItem(this._focusable()[0]);
  }

  _focusLast(): void {
    const focusable = this._focusable();

    this._focusItem(focusable[focusable.length - 1]);
  }

  private _focusItem(item: MudMenuItem | undefined): void {
    if (!item) return;

    this._active.set(item);
    item.focus();
  }

  private _focusRelative(offset: 1 | -1): void {
    const focusable = this._focusable();

    if (focusable.length === 0) return;

    const activeEl = typeof document !== 'undefined' ? document.activeElement : null;
    const currentIndex = focusable.findIndex((item) => item._host.nativeElement === activeEl);
    const from = currentIndex >= 0 ? currentIndex : this._focusable().indexOf(this._active()!);
    const target = focusable[(from + offset + focusable.length) % focusable.length] ?? focusable[0];

    this._focusItem(target);
  }

  protected _onPanelKeydown(event: KeyboardEvent): void {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this._focusRelative(1);
        break;
      case 'ArrowUp':
        event.preventDefault();
        this._focusRelative(-1);
        break;
      case 'Home':
        event.preventDefault();
        this._focusFirst();
        break;
      case 'End':
        event.preventDefault();
        this._focusLast();
        break;
      case 'ArrowLeft': {
        const trigger = this._attachedTrigger();

        if (trigger?.isSubmenu) {
          event.preventDefault();
          event.stopPropagation();
          trigger.close(true);
        }

        break;
      }
      case 'Escape': {
        event.preventDefault();
        event.stopPropagation();

        this.closed.emit();
        this._attachedTrigger()?.close(true);

        break;
      }
      case 'Tab': {
        this.closed.emit();
        this._attachedTrigger()?.closeAll(true);

        break;
      }
    }
  }
}

