   * @docs-private The read still registers the reactive dependency before NG0950 is
   * thrown, so effects/computeds using this re-run once the binding lands.
   * */
  _valueOrUnset(): T | typeof VALUE_UNSET {
    try {
      return this.value();
    } catch {
      return VALUE_UNSET;
    }
  }

