  selector: 'mud-segmented-control',
  styleUrl: './mud-segmented-control.component.scss',
  encapsulation: ViewEncapsulation.None,
  template: '<ng-content />',
  host: {
    class: 'segmented-control',
    role: 'radiogroup',
