@use '../../../src/lib/styles/abstracts/mixins/host';

@include host.typography('mud-spinner');

.spinner {
  box-sizing: border-box;
  display: inline-block;
  flex-shrink: 0;
  border-radius: 50%;
  border-style: solid;
  border-top-color: transparent !important;
  rotate: 45deg;
  animation: spinner-rotate 0.8s linear infinite;

  &--extra-small {
    width: 16px;
    height: 16px;
    border-width: 2px;
  }

  &--small {
    width: 20px;
    height: 20px;
    border-width: 2px;
  }

  &--medium {
    width: 32px;
    height: 32px;
    border-width: 3px;
  }

  &--large {
    width: 40px;
    height: 40px;
    border-width: 4px;
  }

  &--brand {
    border-color: var(--mud-color-background-brand-default, var(--mud-blue-sky-600));
  }

  &--dark {
    border-color: var(--mud-color-background-base-inverse-default, var(--mud-gray-900));
  }

  &--light {
    border-color: var(--mud-color-text-base-inverse-default, var(--mud-white-1000));
  }

  &--light-on-color {
    border-color: var(--mud-color-text-base-inverse-on-color, var(--mud-white-1000));
  }
}

.mud-spinner-label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
  }
}

