export class MudTabGroup {
  private readonly _destroyRef = inject(DestroyRef);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  readonly tabs = contentChildren(MudTab);

  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });
  readonly ariaLabelledby = input<string | undefined>(undefined, { alias: 'aria-labelledby' });
  readonly contentTabIndex = input<number | null>(null);
  readonly stretchTabs = input(false, { transform: booleanAttribute });
  readonly size = input<'md' | 'sm'>('md');
  readonly selectedIndex = model(0);

  readonly selectedTabChange = output<MudTabChangeEvent>();

  protected readonly focusedIndex = signal(0);
  protected readonly canScrollStart = signal(false);
  protected readonly canScrollEnd = signal(false);

  private readonly _buttons = viewChildren<ElementRef<HTMLButtonElement>>('tabButton');
  private readonly _viewport = viewChild<ElementRef<HTMLElement>>('viewport');
  private readonly _strip = viewChild<ElementRef<HTMLElement>>('tabStrip');

  private _lastEmitted = -1;
  private _initialized = false;

  constructor() {
    afterNextRender(() => {
      this.updateOverflow();

      if (typeof ResizeObserver === 'undefined') {
        return;
      }

      const observer = new ResizeObserver(() => this.updateOverflow());
      const viewport = this._viewport()?.nativeElement;
      const strip = this._strip()?.nativeElement;

      if (viewport) {
        observer.observe(viewport);
      }

      if (strip) {
        observer.observe(strip);
      }

      this._destroyRef.onDestroy(() => observer.disconnect());
    });

    effect(() => {
      const tabs = this.tabs();
      const index = this.selectedIndex();

      /**
       * The selected tab can disappear (an @if/@for removes it) or become
       * disabled (programmatic selectedIndex writes bypass the interactive
       * guard; a selected tab's [disabled] can flip). Either way the
       * selection must land on an enabled tab, otherwise no panel is shown —
       * or a disabled tab is presented as active — and every tab button
       * keeps tabindex="-1", making the tablist unreachable by keyboard.
       * */
      if (tabs.length > 0 && (!tabs[index] || tabs[index].disabled())) {
        const fallback = this._closestEnabled(tabs[index] ? index : tabs.length - 1);

        if (fallback >= 0 && fallback !== index) {
          this.selectedIndex.set(fallback);

          return;
        }
      }

      tabs.forEach((tab, i) => {
        tab._position.set(i);
        tab._isActive.set(i === index);
      });

      const tab = tabs[index];

      if (tab) {
        if (this._initialized && index !== this._lastEmitted) {
          this.selectedTabChange.emit({ index, tab });
        }

        this._lastEmitted = index;
        this._initialized = true;
      }
    });
  }

  selectTab(index: number): void {
    const tabs = this.tabs();

    if (index < 0 || index >= tabs.length || tabs[index].disabled()) {
      return;
    }

    this.selectedIndex.set(index);
    this.focusedIndex.set(index);
  }

  focusTab(index: number): void {
    if (!this._isBrowser) return;

    if (index >= 0 && index < this.tabs().length) {
      this.focusedIndex.set(index);

      const button = this._buttons()[index]?.nativeElement;

      button?.focus();
      button?.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
    }
  }

  protected updateOverflow(): void {
    const viewport = this._viewport()?.nativeElement;

    if (!viewport) {
      this.canScrollStart.set(false);
      this.canScrollEnd.set(false);

      return;
    }

    const maxScroll = viewport.scrollWidth - viewport.clientWidth;
    const left = viewport.scrollLeft;

    this.canScrollStart.set(left > 1);
    this.canScrollEnd.set(maxScroll > 1 && left < maxScroll - 1);
  }

  protected scrollByStep(direction: 1 | -1): void {
    const viewport = this._viewport()?.nativeElement;

    viewport?.scrollBy({ left: direction * viewport.clientWidth * 0.75, behavior: 'smooth' });
  }

  protected onKeydown(event: KeyboardEvent): void {
    const count = this.tabs().length;

    if (count === 0) {
      return;
    }

    // Automatic activation (official): arrows move focus AND selection.
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        this._activate(this._nextEnabled(this.focusedIndex(), 1));
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        this._activate(this._nextEnabled(this.focusedIndex(), -1));
        break;
      case 'Home':
        this._activate(this._nextEnabled(-1, 1));
        break;
      case 'End':
        this._activate(this._nextEnabled(count, -1));
        break;
      case 'Enter':
      case ' ':
        this.selectTab(this.focusedIndex());
        break;
      default:
        return;
    }

    event.preventDefault();
  }

  private _activate(index: number): void {
    this.selectTab(index);
    this.focusTab(index);
  }

  private _closestEnabled(from: number): number {
    const tabs = this.tabs();

    for (let i = Math.min(from, tabs.length - 1); i >= 0; i--) {
      if (!tabs[i].disabled()) return i;
    }

    for (let i = from + 1; i < tabs.length; i++) {
      if (!tabs[i].disabled()) return i;
    }

    return -1;
  }

  private _nextEnabled(from: number, direction: 1 | -1): number {
    const tabs = this.tabs();
    const count = tabs.length;
    let index = from;

    for (let step = 0; step < count; step++) {
      index = (index + direction + count) % count;

      if (!tabs[index].disabled()) {
        return index;
      }
    }

    return Math.max(0, Math.min(from, count - 1));
  }
}

