@if (_hasLabel()) {
  <label class="input-field__label" [attr.for]="_id" [id]="_labelId">
    <span class="input-field__label-text"><ng-content select="mud-label" /></span>
    @if (required()) {
      <span class="input-field__required" aria-hidden="true">*</span>
    }
  </label>
}

<div class="input-field__control input-field__control--textarea">
  <textarea
    #native
    class="input-field__native"
    [id]="_id"
    [value]="value()"
    [rows]="rows()"
    [attr.name]="name() || null"
    [attr.placeholder]="placeholder() ?? null"
    [disabled]="_effectiveDisabled()"
    [readOnly]="readonly()"
    [required]="required()"
    [attr.minlength]="minLength() ?? null"
    [attr.maxlength]="maxLength() ?? null"
    [attr.aria-label]="_ariaLabel()"
    [attr.aria-labelledby]="_hasLabel() ? _labelId : null"
    [attr.aria-describedby]="_describedBy()"
    [attr.aria-invalid]="_effectiveInvalid() ? 'true' : null"
    (input)="_onInput($event)"
    (focus)="_onFocus()"
    (blur)="_onBlur()"
  ></textarea>
</div>

@if (_hasMessages() || _showCounter()) {
  <div class="input-field__footer">
    @if (_hasMessages()) {
      <!-- Field-owned wrapper: stable id + role=alert survive whatever the
           consumer projects; alert announces on insertion (WCAG 4.1.3). -->
      <div class="input-field__assistive" role="alert" [id]="_assistiveId">
        <ng-content select="mud-inline-message" />
      </div>
    }
    @if (_showCounter()) {
      <span class="input-field__counter" [id]="_counterId">
        @if (counterLabel(); as srText) {
          <span aria-hidden="true">{{ value().length }} / {{ maxLength() }}</span>
          <span class="input-field__sr-only">{{ srText }}</span>
        } @else {
          {{ value().length }} / {{ maxLength() }}
        }
      </span>
    }
  </div>
}

