  viewChild,
  ViewContainerRef,
  ViewEncapsulation,
} from '@angular/core';
import type { ElementRef, TemplateRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { CdkTrapFocus } from '@angular/cdk/a11y';
import { Overlay } from '@angular/cdk/overlay';
import type { OverlayRef } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import type { ControlValueAccessor } from '@angular/forms';
import type { FormValueControl } from '@angular/forms/signals';
import { MudLabel } from 'ngx-mud-ui/label';
import { MudInlineMessage } from 'ngx-mud-ui/inline-message';
import {
  isSelectable,
  isValidTime,
  MUD_TIME_PATTERN,
  minuteStepTransform,
  toValidTimeOrUndefined,
} from './time-core';
import type { MudMinuteStep, MudTimeValue } from './time-core';
import { MUD_TIME_LABELS } from './time-labels';
import {
  caretForDigitIndex,
  digitsBefore,
  displayToTime,
  formatMasked,
  padHourOnSeparator,
} from './time-mask';
import { MudTimePicker } from './mud-time-picker.component';
import { _MudInputFieldStyles, MudStyleLoader } from 'ngx-mud-ui/core';

declare const ngDevMode: boolean | undefined;

export type MudTimeInputSize = 'medium' | 'large';
export type MudTimeInputVariant = 'default' | 'warning' | 'destructive' | 'success';

let nextUniqueId = 0;

/** A placeholder doubles as the ghost pattern, so it must mirror `HH:MM`: digits would blend into typed input. */
const PLACEHOLDER_SHAPE = /^[^\d:]{2}:[^\d:]{2}$/;

/**
 * ```html
 * <mud-time-input [formField]="form.start" required>
 *   <mud-label>Ora de început</mud-label>
 *   @if (form.start().touched() && form.start().invalid()) {
 *     <mud-inline-message variant="error">Alegeți o oră.</mud-inline-message>
 *   }
 * </mud-time-input>
 * ```
 */
@Component({
  selector: 'mud-time-input',
  templateUrl: './mud-time-input.component.html',
  styleUrl: './mud-time-input.component.scss',
  encapsulation: ViewEncapsulation.None,
  imports: [MudTimePicker, CdkTrapFocus],
  host: {
    '[class]': '_hostClasses()',
  },
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MudTimeInput),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudTimeInput implements ControlValueAccessor, FormValueControl<MudTimeValue> {
  /** @description `HH:MM` (24-hour) or `null`. Two-way bindable; driven by both forms systems. */
  readonly value = model<MudTimeValue>(null);

  /** @description Whether the picker popover is open. Two-way bindable. */
  readonly open = model(false);

  /** @description Trailing clear (×) button, shown only while the field holds text. */
  readonly clearable = input(false, { transform: booleanAttribute });

  readonly variant = input<MudTimeInputVariant>('default');
  readonly size = input<MudTimeInputSize>('medium');
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });
  readonly readonly = input(false, { transform: booleanAttribute });
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly name = input<string>('');

  /** @description Format pattern shown while empty and as the typing ghost: two non-digits, `:`, two non-digits (e.g. `OO:MM`). Defaults to `HH:MM`. */
  readonly placeholder = input<string | undefined>(undefined);

  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });
  readonly ariaDescribedby = input<string | undefined>(undefined, { alias: 'aria-describedby' });

  /** @description Earliest accepted time, `HH:MM` inclusive. Forwarded to the picker. */
  readonly min = input<string | undefined>(undefined);

  /** @description Latest accepted time, `HH:MM` inclusive. Forwarded to the picker. */
  readonly max = input<string | undefined>(undefined);

  /** @description Minute granularity: only these minutes are rendered and accepted. */
  readonly minuteStep = input<MudMinuteStep, unknown>(1, { transform: minuteStepTransform('mud-time-input') });

  /** @description Return `true` for a SELECTABLE time. Runs after min/max and minuteStep. */
  readonly timeFilter = input<((time: string) => boolean) | undefined>(undefined);

  readonly cleared = output<void>();
  readonly touch = output<void>();

  private readonly _labelsSource = inject(MUD_TIME_LABELS);

  /** Normalized token view: a plain object and a live signal both read here. */
  protected readonly _labels = computed(() =>
    isSignal(this._labelsSource) ? this._labelsSource() : this._labelsSource,
  );

  private readonly _overlay = inject(Overlay);
  private readonly _viewContainerRef = inject(ViewContainerRef);
  private readonly _injector = inject(Injector);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  private readonly _control = viewChild.required<ElementRef<HTMLElement>>('control');
  private readonly _native = viewChild.required<ElementRef<HTMLInputElement>>('native');
  private readonly _panelTemplate = viewChild.required<TemplateRef<unknown>>('panel');
  private readonly _picker = viewChild(MudTimePicker);

  /** @docs-private Projected label element (ngx-mud-ui/label). */
  protected readonly _label = contentChild(MudLabel);

  /** @docs-private Consumer-projected assistive messages. */
  private readonly _messages = contentChildren(MudInlineMessage);

  protected readonly _hasLabel = computed(() => !!this._label());
  protected readonly _hasMessages = computed(() => this._messages().length > 0);

  protected readonly _id = `mud-time-input-${nextUniqueId++}`;
  protected readonly _labelId = `${this._id}-label`;
  protected readonly _assistiveId = `${this._id}-assistive`;
  protected readonly _hintId = `${this._id}-hint`;
  protected readonly _dialogId = `${this._id}-dialog`;
  protected readonly _pattern = computed(() => {
    const custom = this.placeholder()?.trim();

    return custom && PLACEHOLDER_SHAPE.test(custom) ? custom : MUD_TIME_PATTERN;
  });

  protected readonly _focused = signal(false);
  private _overlayRef: OverlayRef | null = null;

  private readonly _cvaDisabled = signal(false);
  private _onChange: (value: MudTimeValue) => void = () => undefined;
  private _onTouched: () => void = () => undefined;

  protected readonly _valueTime = computed<string | null>(() => {
    const value = this.value();

    return isValidTime(value) ? value : null;
  });

  protected readonly _minTime = computed(() => toValidTimeOrUndefined(this.min()));
  protected readonly _maxTime = computed(() => toValidTimeOrUndefined(this.max()));

  protected readonly _draft = linkedSignal<string, string>({
    source: () => this._valueTime() ?? '',
    computation: (display, previous) =>
      previous && previous.source === display ? previous.value : display,
  });

  protected readonly _ghost = computed(() => this._pattern().slice(this._draft().length));

  private _lastValue: string | null = null;

  /** What this component last emitted; a `value` that differs arrived from outside. */
  private _lastEmitted: MudTimeValue = null;

  protected readonly _effectiveDisabled = computed(() => this.disabled() || this._cvaDisabled());
  protected readonly _effectiveInvalid = computed(() => this.invalid());

  protected readonly _effectiveVariant = computed<MudTimeInputVariant>(() =>
    this._effectiveInvalid() ? 'destructive' : this.variant(),
  );

  protected readonly _showClear = computed(
    () =>
      this.clearable() &&
      !this._effectiveDisabled() &&
      !this.readonly() &&
      this._draft().length > 0,
  );

  protected readonly _formatHint = computed(() => this._labels().formatHint(this._pattern()));

  protected readonly _describedBy = computed<string>(() => {
    const ids = [this._hintId];

    if (this._hasMessages()) ids.push(this._assistiveId);

    const external = this.ariaDescribedby()?.trim();

    if (external) ids.push(external);

    return ids.join(' ');
  });

  protected readonly _ariaLabel = computed<string | null>(() =>
    this._hasLabel() ? null : (this.ariaLabel() ?? null),
  );

  protected readonly _hostClasses = computed(() => {
    const classes = ['input-field', 'time-field', `input-field--${this._effectiveVariant()}`];

    if (this.size() === 'large') classes.push('input-field--lg');

    if (this.open()) classes.push('is-open');

    if (this._effectiveDisabled()) classes.push('is-disabled');

    if (this.readonly()) classes.push('is-readonly');

    if (this._effectiveInvalid()) classes.push('is-invalid');

    if ((this._focused() || this.open()) && !this._effectiveDisabled()) classes.push('is-focused');

    return classes.join(' ');
  });

  constructor() {
    inject(MudStyleLoader).load(_MudInputFieldStyles);

    effect(() => {
      if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

      const placeholder = this.placeholder()?.trim();

      if (!placeholder || PLACEHOLDER_SHAPE.test(placeholder)) return;

      console.warn(
        `[mud-time-input] placeholder ${JSON.stringify(placeholder)} does not have the HH:MM shape ` +
          `(two non-digits, ':', two non-digits); using 'HH:MM'.`,
      );
    });

    effect(() => {
      if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

      const value = this.value();

      if (value === null || value === '' || isValidTime(value)) return;

      console.warn(
        `[mud-time-input] expected a 24-hour 'HH:MM' time, received ${JSON.stringify(value)}. Rendering as empty.`,
      );
    });

    effect(() => {
      const display = this._draft();

      if (!this._isBrowser) return;

      const native = this._native().nativeElement;

      if (native.value !== display) native.value = display;
    });

    effect(() => {
      if (this.value() !== this._lastEmitted) this._lastValue = null;
    });

    effect(() => {
      if (!this._isBrowser) return;

      if (this.open() && (this._effectiveDisabled() || this.readonly())) {
        this.open.set(false);

        return;
      }

      if (this.open()) this._attachPanel();
      else this._detachPanel();
    });

    inject(DestroyRef).onDestroy(() => this._detachPanel());
  }

  // ----- ControlValueAccessor -----

  writeValue(value: MudTimeValue): void {
    this._lastValue = null;
    this.value.set(value);
  }

  registerOnChange(fn: (value: MudTimeValue) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._cvaDisabled.set(isDisabled);
  }

  focus(options?: FocusOptions): void {
    if (!this._isBrowser) return;

    this._native().nativeElement.focus(options);
  }

  // ----- typing -----

  private _maskAndRestoreCaret(native: HTMLInputElement): string {
    const raw = native.value;
    const caret = native.selectionStart ?? raw.length;
    const masked = formatMasked(raw);

    if (masked !== raw) {
      const offset =
        caret >= raw.length ? masked.length : caretForDigitIndex(masked, digitsBefore(raw, caret));

      native.value = masked;
      native.setSelectionRange?.(offset, offset);
    }

    return masked;
  }

  private _rememberUsable(): void {
    const time = this._valueTime();

    if (time) this._lastValue = time;
  }

  protected _onInput(event: Event): void {
    this._rememberUsable();

    const masked = this._maskAndRestoreCaret(event.target as HTMLInputElement);

    if (masked === '') this._lastValue = null;

    this._commitFrom(masked);
    this._draft.set(masked);
  }

  private _commitFrom(display: string): void {
    this._emit(this._usableTime(display));
  }

  private _usableTime(display: string): string | null {
    const time = displayToTime(display);

    if (!time) return null;

    const constraints = {
      min: this._minTime(),
      max: this._maxTime(),
      minuteStep: this.minuteStep(),
      timeFilter: this.timeFilter(),
    };

    return isSelectable(time, constraints) ? time : null;
  }

  private _emit(value: MudTimeValue): void {
    this._lastEmitted = value;
    this.value.set(value);
    this._onChange(value);
  }

  protected _onFocus(): void {
    this._focused.set(true);
  }

  protected _onBlur(): void {
    this._focused.set(false);
    this._settleOnBlur();
    this._onTouched();
    this.touch.emit();
  }

  private _settleOnBlur(): void {
    const display = this._draft();

    if (display === (this._valueTime() ?? '')) return;

    const settled = display ? (this._usableTime(display) ?? this._lastValue) : null;

    if (settled !== this._valueTime()) this._emit(settled);

    if (this._draft() !== (settled ?? '')) this._draft.set(settled ?? '');
  }

  protected _onKeydown(event: KeyboardEvent): void {
    if (event.altKey && event.key === 'ArrowDown') {
      event.preventDefault();
      this._openPanel();

      return;
    }

    if (event.key === 'Escape' && this.open()) {
      event.preventDefault();
      this._close(false);

      return;
    }

    const native = event.target as HTMLInputElement;
    const padded = padHourOnSeparator(native.value, event.key);

    if (padded === null) return;

    event.preventDefault();
    this._rememberUsable();
    native.value = padded;
    native.setSelectionRange?.(padded.length, padded.length);
    this._commitFrom(padded);
    this._draft.set(padded);
  }

  protected _onClear(): void {
    this._lastValue = null;
    this._draft.set('');
    this._emit(null);
    this.cleared.emit();
    this.focus();
  }

  // ----- popover -----

  protected _toggle(): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    if (this.open()) this._close();
    else this._openPanel();
  }

  private _openPanel(): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    this.open.set(true);
  }

  protected _close(returnFocus = true): void {
    this.open.set(false);

    if (returnFocus) this.focus();
  }

  protected _onPickerChange(value: MudTimeValue): void {
    this._emit(value);
    this._close();
  }

  protected _onPanelKeydown(event: KeyboardEvent): void {
    if (event.key === 'Escape') {
      event.preventDefault();
      this._close();
    }
  }

  private _attachPanel(): void {
    if (this._overlayRef?.hasAttached()) return;

    const control = this._control().nativeElement;
    const positionStrategy = this._overlay
      .position()
      .flexibleConnectedTo(control)
      .withFlexibleDimensions(false)
      .withViewportMargin(8)
      .withPush(false)
      .withPositions([
        { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 4 },
        { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -4 },
      ]);

    this._overlayRef = this._overlay.create({
      positionStrategy,
      scrollStrategy: this._overlay.scrollStrategies.reposition(),
    });

    this._overlayRef.attach(new TemplatePortal(this._panelTemplate(), this._viewContainerRef));

    afterNextRender(() => this._picker()?.focus(), { injector: this._injector });

    this._overlayRef.outsidePointerEvents().subscribe((event) => {
      const target = event.target as Node | null;

      if (target && !control.contains(target)) this._close(false);
    });
  }

  private _detachPanel(): void {
    this._overlayRef?.dispose();
    this._overlayRef = null;
  }
}

styleUrlsData.data:
@use '../../../src/lib/styles/abstracts/mixins/field-panel';
@use '../../../src/lib/styles/abstracts/mixins/host';

@include host.typography('mud-time-input');

.time-field .time-field__control {
  align-items: center;
  display: flex;
  gap: var(--mud-spacing-4, 4px);
}

.time-field__entry {
  display: inline-grid;
  flex: 1 1 auto;
  min-width: 0;
}

.time-field__entry > .time-field__native,
.time-field__entry > .time-field__ghost-row {
  grid-area: 1 / 1;
  font-family: var(--mud-font-family-base);
  font-size: var(--_if-font-size);
  line-height: var(--_if-line-height);
  letter-spacing: inherit;
}

// Two classes: restyles the shared `.input-field__native` by specificity, not load order
// (its 4-class disabled state still wins, as it should).
.input-field__native.time-field__native {
  background: transparent;
  border: 0;
  caret-color: var(--mud-color-text-brand-default);
  color: inherit;
  min-width: 0;
  outline: none;
  padding: 0;
  position: relative;
  width: 100%;
  z-index: 1;
}

.time-field__ghost-row {
  overflow: hidden;
  pointer-events: none;
  white-space: pre;
}

.time-field__ghost-row--hidden {
  visibility: hidden;
}

.time-field__ghost-typed {
  visibility: hidden;
}

.time-field__ghost {
  color: var(--mud-color-text-base-secondary);
}

.time-field.is-disabled .time-field__ghost {
  color: var(--mud-color-text-disabled-default);
}

.time-field__toggle {
  align-items: center;
  background: none;
  border: 0;
  border-radius: var(--mud-border-radius-6, 6px);
  color: var(--mud-color-icon-base-secondary);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  height: 24px;
  justify-content: center;
  padding: 0;
  position: relative;
  width: 24px;

  &:hover:not(:disabled) {
    color: var(--mud-color-icon-base-default);
  }

  @media (pointer: coarse) {
    &::before {
      content: '';
      inset: -8px;
      position: absolute;
    }
  }

  &:focus-visible {
    outline: var(--mud-focus-ring-outer-width, 3px) solid
      var(--mud-focus-ring-outer-color, var(--mud-blue-sky-500));
    outline-offset: 2px;
  }

  &:disabled {
    color: var(--mud-color-text-disabled-default);
    cursor: default;
  }

  svg {
    height: 20px;
    width: 20px;
  }
}

.time-field__toggle-icon--lg,
.input-field--lg .time-field__toggle-icon--md {
  display: none;
}

.input-field--lg .time-field__toggle-icon--lg {
  display: block;
  height: 24px;
  width: 24px;
}

.time-field__panel {
  @include field-panel.field-panel;
}

components.sourceCode:
import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  computed,
  ElementRef,
  inject,
  Injector,
  input,
  isSignal,
  linkedSignal,
  model,
  PLATFORM_ID,
  signal,
  ViewEncapsulation,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { formatTime, isSelectable, minutesForStep, minuteStepTransform, parseTime, toValidTimeOrUndefined } from './time-core';
import type { MudMinuteStep, MudTimeValue } from './time-core';
import { MUD_TIME_LABELS } from './time-labels';

export type MudTimePickerAppearance = 'elevated' | 'flat';
export type MudTimePickerColumn = 'hours' | 'minutes';

const HOURS: readonly number[] = Array.from({ length: 24 }, (_, i) => i);

/** Rows visible at once (Figma 13810:9451); the columns scroll the rest. */
const VISIBLE_ROWS = 7;

/**
 * ```html
 * <mud-time-picker [(value)]="time" min="09:00" max="17:00" />
 * ```
 */
@Component({
  selector: 'mud-time-picker',
  templateUrl: './mud-time-picker.component.html',
  styleUrl: './mud-time-picker.component.scss',
  encapsulation: ViewEncapsulation.None,
  host: {
    '[class]': '_hostClasses()',
    '[attr.role]': 'appearance() === "flat" ? null : "group"',
    '[attr.aria-label]': 'appearance() === "flat" ? null : _labels().picker',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudTimePicker {
  /** @description Selected time, `HH:MM`. Set once an hour AND a minute are picked. */
  readonly value = model<MudTimeValue>(null);

  /** @description Earliest selectable time, `HH:MM` inclusive. */
  readonly min = input<string | undefined>(undefined);

  /** @description Latest selectable time, `HH:MM` inclusive. */
  readonly max = input<string | undefined>(undefined);

  /** @description `flat` drops the card shadow, for a picker inside your own surface. */
  readonly appearance = input<MudTimePickerAppearance>('elevated');

  /** @description Minute granularity: only these minutes are rendered and accepted. */
  readonly minuteStep = input<MudMinuteStep, unknown>(1, { transform: minuteStepTransform('mud-time-picker') });

  /** @description Return `true` for a SELECTABLE time. Runs after min/max and minuteStep. */
  readonly timeFilter = input<((time: string) => boolean) | undefined>(undefined);

  private readonly _labelsSource = inject(MUD_TIME_LABELS);

  /** Normalized token view: a plain object and a live signal both read here. */
  protected readonly _labels = computed(() =>
    isSignal(this._labelsSource) ? this._labelsSource() : this._labelsSource,
  );

  private readonly _host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _injector = inject(Injector);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  protected readonly _columns: readonly MudTimePickerColumn[] = ['hours', 'minutes'];
  protected readonly _separatorRows: readonly number[] = Array.from({ length: VISIBLE_ROWS }, (_, i) => i);

  private readonly _minTime = computed(() => toValidTimeOrUndefined(this.min()));
  private readonly _maxTime = computed(() => toValidTimeOrUndefined(this.max()));

  /** Hour half of the selection: written by a pick, reset by an external `value`. */
  protected readonly _hours = linkedSignal<MudTimeValue, number | null>({
    source: this.value,
    computation: (value, previous) =>
      previous && previous.source === value ? previous.value : (parseTime(value)?.hours ?? null),
  });

  protected readonly _minutes = linkedSignal<MudTimeValue, number | null>({
    source: this.value,
    computation: (value, previous) =>
      previous && previous.source === value ? previous.value : (parseTime(value)?.minutes ?? null),
  });

  /** The column being edited: its selection is solid, the other's is tinted. */
  protected readonly _activeColumn = signal<MudTimePickerColumn>('hours');

  private readonly _focusedHour = signal<number | null>(null);
  private readonly _focusedMinute = signal<number | null>(null);

  private readonly _minuteOptions = computed(() => minutesForStep(this.minuteStep()));

  private readonly _constraints = computed(() => ({
    min: this._minTime(),
    max: this._maxTime(),
    minuteStep: this.minuteStep(),
    timeFilter: this.timeFilter(),
  }));

  /** Hours with no selectable rendered minute. */
  private readonly _disabledHours = computed<ReadonlySet<number>>(() => {
    const constraints = this._constraints();
    const minutes = this._minuteOptions();
    const out = new Set<number>();

    for (const h of HOURS) {
      if (!minutes.some((m) => isSelectable(formatTime(h, m), constraints))) out.add(h);
    }

    return out;
  });

  /** Minutes not selectable for the chosen hour; while no hour is chosen, minutes no hour can select. */
  private readonly _disabledMinutes = computed<ReadonlySet<number>>(() => {
    const constraints = this._constraints();
    const hours = this._hours();
    const out = new Set<number>();

    for (const m of this._minuteOptions()) {
      const selectable =
        hours === null
          ? HOURS.some((h) => isSelectable(formatTime(h, m), constraints))
          : isSelectable(formatTime(hours, m), constraints);

      if (!selectable) out.add(m);
    }

    return out;
  });

  protected readonly _hourTabStop = computed(() => this._tabStop('hours'));
  protected readonly _minuteTabStop = computed(() => this._tabStop('minutes'));

  protected readonly _hostClasses = computed(() =>
    ['time-picker', `time-picker--${this.appearance()}`].join(' '),
  );

  constructor() {
    // Open with each selected value at the top of its column (Figma 13810:9450).
    afterNextRender(() => this._scrollSelectedToTop());
  }

  /** Moves focus onto the active column's tab stop. */
  focus(): void {
    if (!this._isBrowser) return;

    const column = this._activeColumn();

    this._option(column, this._tabStop(column))?.focus();
  }

  protected _options(column: MudTimePickerColumn): readonly number[] {
    return column === 'hours' ? HOURS : this._minuteOptions();
  }

  protected _selected(column: MudTimePickerColumn): number | null {
    return column === 'hours' ? this._hours() : this._minutes();
  }

  protected _tabStopOf(column: MudTimePickerColumn): number {
    return column === 'hours' ? this._hourTabStop() : this._minuteTabStop();
  }

  protected _isDisabled(column: MudTimePickerColumn, n: number): boolean {
    if (!this._options(column).includes(n)) return true;

    return (column === 'hours' ? this._disabledHours() : this._disabledMinutes()).has(n);
  }

  protected _pad(n: number): string {
    return String(n).padStart(2, '0');
  }

  protected _pick(column: MudTimePickerColumn, n: number): void {
    if (this._isDisabled(column, n)) return;

    if (column === 'hours') {
      this._hours.set(n);
      this._focusedHour.set(n);

      // A minute the new hour puts out of bounds cannot stay selected.
      const minutes = this._minutes();

      if (minutes !== null && this._isDisabled('minutes', minutes)) this._minutes.set(null);

      // First pass moves on to the minutes; re-editing a complete time stays
      // on the hour just picked instead of pulling focus away.
      if (this._minutes() === null) this._editColumn('minutes');
      else this._activeColumn.set('hours');

      return;
    }

    this._minutes.set(n);
    this._focusedMinute.set(n);

    const hours = this._hours();

    if (hours === null) {
      this._editColumn('hours');

      return;
    }

    this.value.set(formatTime(hours, n));
  }

  protected _onOptionFocus(column: MudTimePickerColumn, n: number): void {
    this._activeColumn.set(column);

    if (column === 'hours') this._focusedHour.set(n);
    else this._focusedMinute.set(n);
  }

  /** Bound on each listbox; the option under the event is the one that acts. */
  protected _onKeydown(event: KeyboardEvent, column: MudTimePickerColumn): void {
    const option = (event.target as HTMLElement | null)?.closest<HTMLElement>('[role="option"]');

    if (!option) return;

    const current = Number(option.dataset['value']);

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this._moveFocus(column, this._stepFrom(column, current, 1));
        break;
      case 'ArrowUp':
        event.preventDefault();
        this._moveFocus(column, this._stepFrom(column, current, -1));
        break;
      case 'Home': {
        event.preventDefault();
        const first = this._nextEnabled(column, -1, 1);

        this._moveFocus(column, first === -1 ? current : first);
        break;
      }
      case 'End': {
        event.preventDefault();
        const last = this._nextEnabled(column, this._options(column).length, -1);

        this._moveFocus(column, last === -1 ? current : last);
        break;
      }
      case 'ArrowRight':
        if (column !== 'hours') return;

        event.preventDefault();
        this._editColumn('minutes');
        break;
      case 'ArrowLeft':
        if (column !== 'minutes') return;

        event.preventDefault();
        this._editColumn('hours');
        break;
      case 'Enter':
      case ' ':
        event.preventDefault();
        this._pick(column, current);
        break;
    }
  }

  private _nextEnabled(column: MudTimePickerColumn, fromIndex: number, direction: 1 | -1): number {
    const all = this._options(column);

    for (let i = fromIndex + direction; i >= 0 && i < all.length; i += direction) {
      if (!this._isDisabled(column, all[i])) return all[i];
    }

    return -1;
  }

  private _stepFrom(column: MudTimePickerColumn, value: number, direction: 1 | -1): number {
    const next = this._nextEnabled(column, this._options(column).indexOf(value), direction);

    return next === -1 ? value : next;
  }

  private _tabStop(column: MudTimePickerColumn): number {
    const focused = column === 'hours' ? this._focusedHour() : this._focusedMinute();
    const selected = this._selected(column);

    if (focused !== null && !this._isDisabled(column, focused)) return focused;

    if (selected !== null && !this._isDisabled(column, selected)) return selected;

    return this._nextEnabled(column, -1, 1);
  }

  /** Makes `column` the one being edited and focuses its tab stop after render. */
  private _editColumn(column: MudTimePickerColumn): void {
    this._activeColumn.set(column);

    if (column === 'hours') this._focusedHour.set(this._tabStop('hours'));
    else this._focusedMinute.set(this._tabStop('minutes'));

    this._focusAfterRender(column);
  }

  private _moveFocus(column: MudTimePickerColumn, n: number): void {
    if (column === 'hours') this._focusedHour.set(n);
    else this._focusedMinute.set(n);

    this._focusAfterRender(column);
  }

  private _option(column: MudTimePickerColumn, n: number): HTMLElement | null {
    return this._host.nativeElement.querySelector<HTMLElement>(
      `[data-column="${column}"] [role="option"][data-value="${n}"]`,
    );
  }

  private _focusAfterRender(column: MudTimePickerColumn): void {
    afterNextRender(
      () => {
        const option = this._host.nativeElement.querySelector<HTMLElement>(
          `[data-column="${column}"] [role="option"][tabindex="0"]`,
        );

        option?.focus();
        option?.scrollIntoView?.({ block: 'nearest' });
      },
      { injector: this._injector },
    );
  }

  private _scrollSelectedToTop(): void {
    for (const column of this._columns) {
      const selected = this._selected(column);

      if (selected === null) continue;

      const list = this._host.nativeElement.querySelector<HTMLElement>(`[data-column="${column}"]`);
      const option = this._option(column, selected);

      if (list && option) list.scrollTop = option.offsetTop;
    }
  }
}

