      [length]="${args.length}"
      [pageSize]="${args.pageSize}"
      [(pageIndex)]="pageIndex"
      [disabled]="${args.disabled}"
      size="${args.size}"
      aria-label="${args['aria-label']}"
      (page)="load($event)"
    />
  \`,
})
export class ResultsComponent {
  readonly pageIndex = signal(${args.pageIndex});
  load(event: MudPageEvent) { /* fetch page event.pageIndex */ }
}`;

