import { MudPagination } from 'ngx-mud-ui/pagination';
import {
  MudCell,
  MudCellDef,
  MudColumnDef,
  MudHeaderCell,
  MudHeaderCellDef,
  MudHeaderRow,
  MudHeaderRowDef,
  MudRow,
  MudRowDef,
  MudSort,
  MudSortHeader,
  MudTable,
  MudTableDataSource,
} from 'ngx-mud-ui/table';

interface Cerere {
  id: number;
  nume: string;
  suma: number;
}

const CERERI: Cerere[] = Array.from({ length: 47 }, (_v, i) => ({
  id: i + 1,
  nume: ['Ana Rusu', 'Ion Ceban', 'Maria Popescu', 'Victor Lungu', 'Elena Cojocaru'][i % 5],
  suma: ((i * 37) % 900) + 100,
}));

@Component({
  selector: 'app-cereri',
  imports: [
