/** Story-only host for the With tree story. */
@Component({
  selector: 'mud-sidebar-story-tree',
  imports: [...SIDEBAR_IMPORTS, ...TOGGLE_IMPORTS, MudTree, MudTreeNode, MudTreeNodeDef, RouterLinkActive],
