const dividerValue = (arg: DividerArg | undefined): boolean | undefined =>
  arg === 'true' ? true : arg === 'false' ? false : undefined;

const dividerAttr = (arg: DividerArg | undefined): string =>
  arg === 'true' || arg === 'false' ? ` [divider]="${arg}"` : '';

