const FILTERS: FilterNode[] = [
  {
    id: 'documents',
    label: 'Documente',
    children: [
      { id: 'passport', label: 'Pașaport' },
      { id: 'id-card', label: 'Buletin' },
      { id: 'license', label: 'Permis de conducere' },
    ],
  },
  {
    id: 'services',
