  }

  const moduleLines = [...byModule].map(([from, symbols]) => {
    const list = from === 'ngx-mud-ui/icons' && o.iconType ? [...symbols, 'type MudIconName'] : symbols;

    return `import { ${list.join(', ')} } from '${from}';`;
